	n.mu.Lock()
	defer n.mu.Unlock()

	// If we see a higher term, convert to follower
	if append.Term > n.currentTerm {
		n.currentTerm = append.Term
		n.state = Follower
		n.votedFor = -1
		n.resetElectionTimer()
		return
	}

