package raft

import "fmt"

// RequestVoteReply represents the reply to a RequestVote RPC
type RequestVoteReply struct {
	Term        int64
	VoteGranted bool
}

// RequestVote handles a RequestVote RPC from a candidate
func (n *RaftNode) RequestVote(args RequestVoteArgs) RequestVoteReply {
	n.mu.Lock()
	defer n.mu.Unlock()

	reply := RequestVoteReply{
		Term:        n.currentTerm,
		VoteGranted: false,
	}

	// If the request term is older than current term, reject
	if args.Term < n.currentTerm {
		return reply
	}

	// If the request term is newer, update current term and convert to follower
	if args.Term > n.currentTerm {
		n.currentTerm = args.Term
		n.state = Follower
		n.votedFor = -1
		n.voteCount = 0
		n.votedPeers = make(map[int64]bool)
		n.resetElectionTimer()
		reply.Term = n.currentTerm
	}

	// If we haven't voted in this term, or already voted for this candidate
	if n.votedFor == -1 || n.votedFor == args.CandidateID {
		// Check log is at least as up-to-date as ours
		if args.LastLogTerm > n.log.LastTerm() ||
			(args.LastLogTerm == n.log.LastTerm() && args.LastLogIndex >= n.log.LastIndex()) {
			n.votedFor = args.CandidateID
			reply.VoteGranted = true
			n.resetElectionTimer()
			fmt.Printf("[Node %d] Voted for Node %d in term %d\n", n.id, args.CandidateID, args.Term)
		}
	}

	return reply
}

// AppendEntriesReply represents the reply to an AppendEntries RPC
type AppendEntriesReply struct {
	Term    int64
	Success bool
}

// AppendEntries handles an AppendEntries RPC from the leader
func (n *RaftNode) AppendEntries(args AppendEntriesArgs) AppendEntriesReply {
	n.mu.Lock()
	defer n.mu.Unlock()

	reply := AppendEntriesReply{
		Term:    n.currentTerm,
		Success: false,
	}

	// If the request term is older than current term, reject
	if args.Term < n.currentTerm {
		return reply
	}

	// If the request term is newer, update current term
	if args.Term > n.currentTerm {
		n.currentTerm = args.Term
		n.state = Follower
		n.votedFor = -1
		n.voteCount = 0
		n.votedPeers = make(map[int64]bool)
	} else if args.Term == n.currentTerm && n.state == Candidate {
		// If we're a candidate and see a valid leader, convert to follower
		n.state = Follower
		n.votedFor = -1
		n.voteCount = 0
		n.votedPeers = make(map[int64]bool)
	}

	reply.Term = n.currentTerm
	n.resetElectionTimer()

	// Check if previous log entry matches
	if args.PrevLogIndex > 0 {
		if args.PrevLogIndex > n.log.LastIndex() {
			// Log is too short
			return reply
		}

		prevEntry, err := n.log.Get(args.PrevLogIndex)
		if err != nil || prevEntry.Term != args.PrevLogTerm {
			// Log mismatch
			return reply
		}
	}

	// Append entries
	for i, entry := range args.Entries {
		logIndex := args.PrevLogIndex + int64(i) + 1
		if logIndex <= n.log.LastIndex() {
			// Check if existing entry matches
			existing, _ := n.log.Get(logIndex)
			if existing.Term != entry.Term {
				// Conflict: remove this and all following entries
				n.log.TruncateFrom(logIndex)
			}
		}
	}

	// Append new entries
	for _, entry := range args.Entries {
		n.log.Append(entry.Term, entry.Command)
	}

	// Update commit index
	if args.LeaderCommit > n.commitIndex {
		if args.LeaderCommit < n.log.LastIndex() {
			n.commitIndex = args.LeaderCommit
		} else {
			n.commitIndex = n.log.LastIndex()
		}
	}

	reply.Success = true
	return reply
}

