package raft

import (
	"fmt"
	"math/rand"
	"sync"
	"time"
)

// NodeState represents the state of a Raft node
type NodeState int

const (
	Follower NodeState = iota
	Candidate
	Leader
)

func (s NodeState) String() string {
	switch s {
	case Follower:
		return "Follower"
	case Candidate:
		return "Candidate"
	case Leader:
		return "Leader"
	default:
		return "Unknown"
	}
}

// RaftNode represents a single Raft node in a cluster
type RaftNode struct {
	// Node identity
	id    int64
	peers []int64

	// Persistent state (should be persisted to stable storage)
	currentTerm int64
	votedFor    int64 // -1 if no vote cast
	log         *Log

	// Volatile state
	commitIndex int64
	lastApplied int64
	state       NodeState

	// Leader only (reinitialized after election)
	nextIndex  map[int64]int64 // for each peer: index of next log entry to send
	matchIndex map[int64]int64 // for each peer: index of highest log entry known to be replicated

	// Election tracking
	voteCount   int64                // votes received in current term
	votedPeers  map[int64]bool      // track which peers have voted in current term

	// RPC responses
	voteCh   chan VoteResponse
	appendCh chan AppendResponse

	// Timers
	electionTimer  *time.Timer
	heartbeatTick  <-chan time.Time
	stopCh         chan struct{}
	mu             sync.RWMutex

	// Callbacks
	onStateChange func(state NodeState)
	onCommit      func(index int64, data []byte)
}

// VoteResponse represents the response to a RequestVote RPC
type VoteResponse struct {
	PeerID      int64
	Term        int64
	VoteGranted bool
}

// AppendResponse represents the response to an AppendEntries RPC
type AppendResponse struct {
	PeerID    int64
	Term      int64
	Success   bool
	NextIndex int64
}

// RequestVoteArgs represents the arguments for RequestVote RPC
type RequestVoteArgs struct {
	Term         int64
	CandidateID  int64
	LastLogIndex int64
	LastLogTerm  int64
}

// AppendEntriesArgs represents the arguments for AppendEntries RPC
type AppendEntriesArgs struct {
	Term         int64
	LeaderID     int64
	PrevLogIndex int64
	PrevLogTerm  int64
	Entries      []LogEntry
	LeaderCommit int64
}

// NewRaftNode creates a new Raft node
func NewRaftNode(id int64, peers []int64) *RaftNode {
	node := &RaftNode{
		id:          id,
		peers:       peers,
		currentTerm: 0,
		votedFor:    -1,
		log:         NewLog(),
		commitIndex: 0,
		lastApplied: 0,
		state:       Follower,
		nextIndex:   make(map[int64]int64),
		matchIndex:  make(map[int64]int64),
		voteCh:      make(chan VoteResponse, 100),
		appendCh:    make(chan AppendResponse, 100),
		stopCh:      make(chan struct{}),
	}

	// Initialize leader state
	for _, peer := range peers {
		node.nextIndex[peer] = node.log.LastIndex() + 1
		node.matchIndex[peer] = 0
	}

	// Initialize election tracking
	node.voteCount = 0
	node.votedPeers = make(map[int64]bool)

	return node
}

// Start starts the Raft node
func (n *RaftNode) Start() {
	go n.run()
}

// Stop stops the Raft node
func (n *RaftNode) Stop() {
	close(n.stopCh)
}

// run is the main event loop for the Raft node
func (n *RaftNode) run() {
	n.resetElectionTimer()
	heartbeatTicker := time.NewTicker(50 * time.Millisecond)
	defer heartbeatTicker.Stop()

	for {
		select {
		case <-n.stopCh:
			return

		case <-n.electionTimer.C:
			n.handleElectionTimeout()

		case <-heartbeatTicker.C:
			if n.getState() == Leader {
				n.sendHeartbeats()
			}

		case vote := <-n.voteCh:
			n.handleVoteResponse(vote)

		case append := <-n.appendCh:
			n.handleAppendResponse(append)
		}
	}
}

// handleElectionTimeout handles election timeout
func (n *RaftNode) handleElectionTimeout() {
	n.mu.Lock()
	defer n.mu.Unlock()

	if n.state == Leader {
		// Leader doesn't have election timeout
		n.resetElectionTimer()
		return
	}

	fmt.Printf("[Node %d] Election timeout! Starting election for term %d\n", n.id, n.currentTerm+1)

	// Convert to Candidate
	n.currentTerm++
	n.state = Candidate
	n.votedFor = n.id
	n.voteCount = 1 // Vote for ourselves
	n.votedPeers = make(map[int64]bool)
	n.votedPeers[n.id] = true

	// Send RequestVote to all peers
	lastLogIndex := n.log.LastIndex()
	lastLogTerm := n.log.LastTerm()

	args := RequestVoteArgs{
		Term:         n.currentTerm,
		CandidateID:  n.id,
		LastLogIndex: lastLogIndex,
		LastLogTerm:  lastLogTerm,
	}

	fmt.Printf("[Node %d] Requesting votes for term %d\n", n.id, n.currentTerm)

	// In a real implementation, this would send RPCs to peers
	// For now, simulate vote collection in handleVoteResponse
	_ = args

	n.resetElectionTimer()
}

// handleVoteResponse handles a vote response
func (n *RaftNode) handleVoteResponse(vote VoteResponse) {
	n.mu.Lock()
	defer n.mu.Unlock()

	// If we got a vote for an older term, ignore it
	if vote.Term < n.currentTerm {
		return
	}

	// If we see a higher term, convert to follower
	if vote.Term > n.currentTerm {
		n.currentTerm = vote.Term
		n.state = Follower
		n.votedFor = -1
		n.voteCount = 0
		n.votedPeers = make(map[int64]bool)
		n.resetElectionTimer()
		return
	}

	// Only Candidate cares about vote responses
	if n.state != Candidate {
		return
	}

	// Ignore duplicate votes from same peer
	if n.votedPeers[vote.PeerID] {
		return
	}

	if vote.VoteGranted {
		fmt.Printf("[Node %d] Received vote from Peer %d\n", n.id, vote.PeerID)
		n.votedPeers[vote.PeerID] = true
		n.voteCount++

		// Check if we have majority (n/2 + 1)
		majority := int64(len(n.peers)/2 + 1)
		if n.voteCount >= majority {
			n.state = Leader
			fmt.Printf("[Node %d] Elected as Leader for term %d\n", n.id, n.currentTerm)

			// Initialize leader state
			for _, peer := range n.peers {
				if peer != n.id {
					n.nextIndex[peer] = n.log.LastIndex() + 1
					n.matchIndex[peer] = 0
				}
			}

			// Send initial heartbeat
			n.resetElectionTimer()
		}
	} else {
		// Vote denied, just log it
		fmt.Printf("[Node %d] Vote denied by Peer %d\n", n.id, vote.PeerID)
	}
}

// handleAppendResponse handles an append response
func (n *RaftNode) handleAppendResponse(append AppendResponse) {
	n.mu.Lock()
	defer n.mu.Unlock()

	// If we see a higher term, convert to follower
	if append.Term > n.currentTerm {
		n.currentTerm = append.Term
		n.state = Follower
		n.votedFor = -1
		n.resetElectionTimer()
		return
	}

	// Only leader processes append responses
	if n.state != Leader {
		return
	}

	if append.Success {
		n.matchIndex[append.PeerID] = append.NextIndex - 1
		n.nextIndex[append.PeerID] = append.NextIndex
	} else {
		// Decrement nextIndex and retry
		n.nextIndex[append.PeerID]--
	}
}

// sendHeartbeats sends heartbeat/empty AppendEntries to all followers
func (n *RaftNode) sendHeartbeats() {
	n.mu.RLock()
	defer n.mu.RUnlock()

	fmt.Printf("[Node %d] → Heartbeat sent to all followers\n", n.id)

	for _, peer := range n.peers {
		// In a real implementation, send AppendEntries RPC to peer
		_ = peer
	}
}

// resetElectionTimer resets the election timer
func (n *RaftNode) resetElectionTimer() {
	// Random timeout between 150-300ms
	timeout := time.Duration(150+rand.Intn(150)) * time.Millisecond
	if n.electionTimer != nil {
		n.electionTimer.Stop()
	}
	n.electionTimer = time.NewTimer(timeout)
}

// getState returns the current state
func (n *RaftNode) getState() NodeState {
	n.mu.RLock()
	defer n.mu.RUnlock()
	return n.state
}

// GetState returns the current state, current term, and whether this node is leader
func (n *RaftNode) GetState() (int64, bool) {
	n.mu.RLock()
	defer n.mu.RUnlock()
	return n.currentTerm, n.state == Leader
}

// AppendEntry appends an entry to the log (only leaders accept client requests)
func (n *RaftNode) AppendEntry(command []byte) error {
	n.mu.Lock()
	defer n.mu.Unlock()

	if n.state != Leader {
		return fmt.Errorf("not leader")
	}

	n.log.Append(n.currentTerm, command)
	fmt.Printf("[Node %d] Appended entry to log: %q\n", n.id, string(command))
	return nil
}

// ID returns the node ID
func (n *RaftNode) ID() int64 {
	return n.id
}

