package raft

import (
	"encoding/binary"
	"fmt"
	"io"
)

// MessageType represents different RPC message types
type MessageType uint8

const (
	MessageRequestVote MessageType = iota + 1
	MessageRequestVoteReply
	MessageAppendEntries
	MessageAppendEntriesReply
)

// Message wraps RPC arguments and replies
type Message struct {
	Type MessageType
	Data []byte
}

// EncodeRequestVote encodes RequestVoteArgs to bytes
func EncodeRequestVote(args RequestVoteArgs) []byte {
	buf := make([]byte, 0, 100)

	// Term (int64)
	termBuf := make([]byte, 8)
	binary.BigEndian.PutUint64(termBuf, uint64(args.Term))
	buf = append(buf, termBuf...)

	// CandidateID (int64)
	candBuf := make([]byte, 8)
	binary.BigEndian.PutUint64(candBuf, uint64(args.CandidateID))
	buf = append(buf, candBuf...)

	// LastLogIndex (int64)
	indexBuf := make([]byte, 8)
	binary.BigEndian.PutUint64(indexBuf, uint64(args.LastLogIndex))
	buf = append(buf, indexBuf...)

	// LastLogTerm (int64)
	termBuf2 := make([]byte, 8)
	binary.BigEndian.PutUint64(termBuf2, uint64(args.LastLogTerm))
	buf = append(buf, termBuf2...)

	return buf
}

// DecodeRequestVote decodes bytes to RequestVoteArgs
func DecodeRequestVote(data []byte) (RequestVoteArgs, error) {
	if len(data) < 32 {
		return RequestVoteArgs{}, fmt.Errorf("invalid request vote data length: %d", len(data))
	}

	args := RequestVoteArgs{
		Term:         int64(binary.BigEndian.Uint64(data[0:8])),
		CandidateID:  int64(binary.BigEndian.Uint64(data[8:16])),
		LastLogIndex: int64(binary.BigEndian.Uint64(data[16:24])),
		LastLogTerm:  int64(binary.BigEndian.Uint64(data[24:32])),
	}

	return args, nil
}

// EncodeRequestVoteReply encodes RequestVoteReply to bytes
func EncodeRequestVoteReply(reply RequestVoteReply) []byte {
	buf := make([]byte, 0, 50)

	// Term (int64)
	termBuf := make([]byte, 8)
	binary.BigEndian.PutUint64(termBuf, uint64(reply.Term))
	buf = append(buf, termBuf...)

	// VoteGranted (bool as 1 byte)
	if reply.VoteGranted {
		buf = append(buf, 1)
	} else {
		buf = append(buf, 0)
	}

	return buf
}

// DecodeRequestVoteReply decodes bytes to RequestVoteReply
func DecodeRequestVoteReply(data []byte) (RequestVoteReply, error) {
	if len(data) < 9 {
		return RequestVoteReply{}, fmt.Errorf("invalid request vote reply data length: %d", len(data))
	}

	reply := RequestVoteReply{
		Term:        int64(binary.BigEndian.Uint64(data[0:8])),
		VoteGranted: data[8] == 1,
	}

	return reply, nil
}

// EncodeAppendEntries encodes AppendEntriesArgs to bytes
func EncodeAppendEntries(args AppendEntriesArgs) []byte {
	buf := make([]byte, 0, 200)

	// Term (int64)
	termBuf := make([]byte, 8)
	binary.BigEndian.PutUint64(termBuf, uint64(args.Term))
	buf = append(buf, termBuf...)

	// LeaderID (int64)
	leaderBuf := make([]byte, 8)
	binary.BigEndian.PutUint64(leaderBuf, uint64(args.LeaderID))
	buf = append(buf, leaderBuf...)

	// PrevLogIndex (int64)
	prevIndexBuf := make([]byte, 8)
	binary.BigEndian.PutUint64(prevIndexBuf, uint64(args.PrevLogIndex))
	buf = append(buf, prevIndexBuf...)

	// PrevLogTerm (int64)
	prevTermBuf := make([]byte, 8)
	binary.BigEndian.PutUint64(prevTermBuf, uint64(args.PrevLogTerm))
	buf = append(buf, prevTermBuf...)

	// LeaderCommit (int64)
	commitBuf := make([]byte, 8)
	binary.BigEndian.PutUint64(commitBuf, uint64(args.LeaderCommit))
	buf = append(buf, commitBuf...)

	// Entries count (uint32)
	entriesBuf := make([]byte, 4)
	binary.BigEndian.PutUint32(entriesBuf, uint32(len(args.Entries)))
	buf = append(buf, entriesBuf...)

	// Entries
	for _, entry := range args.Entries {
		// Term (int64)
		entryTermBuf := make([]byte, 8)
		binary.BigEndian.PutUint64(entryTermBuf, uint64(entry.Term))
		buf = append(buf, entryTermBuf...)

		// Index (int64)
		entryIndexBuf := make([]byte, 8)
		binary.BigEndian.PutUint64(entryIndexBuf, uint64(entry.Index))
		buf = append(buf, entryIndexBuf...)

		// Command length (uint32)
		cmdLenBuf := make([]byte, 4)
		binary.BigEndian.PutUint32(cmdLenBuf, uint32(len(entry.Command)))
		buf = append(buf, cmdLenBuf...)

		// Command
		buf = append(buf, entry.Command...)
	}

	return buf
}

// DecodeAppendEntries decodes bytes to AppendEntriesArgs
func DecodeAppendEntries(data []byte) (AppendEntriesArgs, error) {
	if len(data) < 40 {
		return AppendEntriesArgs{}, fmt.Errorf("invalid append entries data length: %d", len(data))
	}

	args := AppendEntriesArgs{
		Term:         int64(binary.BigEndian.Uint64(data[0:8])),
		LeaderID:     int64(binary.BigEndian.Uint64(data[8:16])),
		PrevLogIndex: int64(binary.BigEndian.Uint64(data[16:24])),
		PrevLogTerm:  int64(binary.BigEndian.Uint64(data[24:32])),
		LeaderCommit: int64(binary.BigEndian.Uint64(data[32:40])),
	}

	entriesCount := binary.BigEndian.Uint32(data[40:44])
	args.Entries = make([]LogEntry, 0, entriesCount)

	offset := 44
	for i := uint32(0); i < entriesCount; i++ {
		if offset+20 > len(data) {
			return AppendEntriesArgs{}, fmt.Errorf("invalid entry header at offset %d", offset)
		}

		term := int64(binary.BigEndian.Uint64(data[offset : offset+8]))
		index := int64(binary.BigEndian.Uint64(data[offset+8 : offset+16]))
		cmdLen := binary.BigEndian.Uint32(data[offset+16 : offset+20])
		offset += 20

		if offset+int(cmdLen) > len(data) {
			return AppendEntriesArgs{}, fmt.Errorf("invalid command at offset %d, len %d", offset, cmdLen)
		}

