	termBuf := make([]byte, 8)
	binary.BigEndian.PutUint64(termBuf, uint64(args.Term))
	buf = append(buf, termBuf...)

	// LeaderID (int64)
	leaderBuf := make([]byte, 8)
	binary.BigEndian.PutUint64(leaderBuf, uint64(args.LeaderID))
	buf = append(buf, leaderBuf...)

	// PrevLogIndex (int64)
	prevIndexBuf := make([]byte, 8)
	binary.BigEndian.PutUint64(prevIndexBuf, uint64(args.PrevLogIndex))
	buf = append(buf, prevIndexBuf...)

	// PrevLogTerm (int64)
	prevTermBuf := make([]byte, 8)
	binary.BigEndian.PutUint64(prevTermBuf, uint64(args.PrevLogTerm))
	buf = append(buf, prevTermBuf...)

	// LeaderCommit (int64)
	commitBuf := make([]byte, 8)
	binary.BigEndian.PutUint64(commitBuf, uint64(args.LeaderCommit))
	buf = append(buf, commitBuf...)

