		binary.BigEndian.PutUint64(entryTermBuf, uint64(entry.Term))
		buf = append(buf, entryTermBuf...)

		// Index (int64)
		entryIndexBuf := make([]byte, 8)
		binary.BigEndian.PutUint64(entryIndexBuf, uint64(entry.Index))
		buf = append(buf, entryIndexBuf...)

