		}

		term := int64(binary.BigEndian.Uint64(data[offset : offset+8]))
		index := int64(binary.BigEndian.Uint64(data[offset+8 : offset+16]))
		cmdLen := binary.BigEndian.Uint32(data[offset+16 : offset+20])
		offset += 20

		if offset+int(cmdLen) > len(data) {
			return AppendEntriesArgs{}, fmt.Errorf("invalid command at offset %d, len %d", offset, cmdLen)
		}

		command := make([]byte, cmdLen)
		copy(command, data[offset:offset+int(cmdLen)])
		offset += int(cmdLen)

		args.Entries = append(args.Entries, LogEntry{
			Term:    term,
			Index:   index,
			Command: command,
		})
	}

	return args, nil
}

// EncodeAppendEntriesReply encodes AppendEntriesReply to bytes
func EncodeAppendEntriesReply(reply AppendEntriesReply) []byte {
	buf := make([]byte, 0, 50)

	// Term (int64)
	termBuf := make([]byte, 8)
	binary.BigEndian.PutUint64(termBuf, uint64(reply.Term))
