// ReadMessage reads a message from a connection with length-prefixed format
func ReadMessage(conn io.Reader) (*Message, error) {
	// Read message type (1 byte)
	typeBuf := make([]byte, 1)
	if _, err := io.ReadFull(conn, typeBuf); err != nil {
