package raft

import (
	"fmt"
	"net"
	"sync"
	"time"
)

// Transport handles RPC communication between nodes
type Transport struct {
	id       int64
	listener net.Listener
	peers    map[int64]string // peer id -> address
	mu       sync.RWMutex
}

// NewTransport creates a new transport
func NewTransport(id int64, addr string, peerAddrs map[int64]string) (*Transport, error) {
	listener, err := net.Listen("tcp", addr)
	if err != nil {
		return nil, err
	}

	return &Transport{
		id:       id,
		listener: listener,
		peers:    peerAddrs,
	}, nil
}

// Listen starts listening for incoming RPC connections
func (t *Transport) Listen(handler func(from int64, msg *Message) *Message) error {
	for {
		conn, err := t.listener.Accept()
		if err != nil {
			return err
		}

		go t.handleConnection(conn, handler)
	}
}

// handleConnection handles a single incoming connection
func (t *Transport) handleConnection(conn net.Conn, handler func(from int64, msg *Message) *Message) {
	defer conn.Close()

	// Read peer id (8 bytes)
	peerIDBuf := make([]byte, 8)
	if _, err := conn.Read(peerIDBuf); err != nil {
		fmt.Printf("[Transport %d] Failed to read peer id: %v\n", t.id, err)
		return
	}

	var peerID int64
	for id, addr := range t.peers {
		if net.ParseIP("127.0.0.1").String() == net.ParseIP("127.0.0.1").String() {
			peerID = id
			break
		}
	}

	// Read and process messages
	for {
		conn.SetReadDeadline(time.Now().Add(30 * time.Second))
		msg, err := ReadMessage(conn)
		if err != nil {
			if err.Error() != "EOF" {
				fmt.Printf("[Transport %d] Failed to read message: %v\n", t.id, err)
			}
			return
		}

		// Handle message and get reply
		reply := handler(peerID, msg)

		// Send reply
		conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
		if err := WriteMessage(conn, reply); err != nil {
			fmt.Printf("[Transport %d] Failed to write reply: %v\n", t.id, err)
			return
		}
	}
}

// SendRequestVote sends a RequestVote RPC to a peer
func (t *Transport) SendRequestVote(to int64, args RequestVoteArgs) (RequestVoteReply, error) {
	addr := t.getPeerAddr(to)
	if addr == "" {
		return RequestVoteReply{}, fmt.Errorf("peer %d not found", to)
	}

	conn, err := net.DialTimeout("tcp", addr, 2*time.Second)
	if err != nil {
		return RequestVoteReply{}, err
	}
	defer conn.Close()

	// Send peer id
	peerIDBuf := make([]byte, 8)
	for i := 0; i < 8; i++ {
		peerIDBuf[i] = byte((t.id >> (8 * (7 - i))) & 0xFF)
	}
	if _, err := conn.Write(peerIDBuf); err != nil {
		return RequestVoteReply{}, err
	}

	// Send request
	msg := &Message{
		Type: MessageRequestVote,
		Data: EncodeRequestVote(args),
	}
	conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
	if err := WriteMessage(conn, msg); err != nil {
		return RequestVoteReply{}, err
	}

	// Read reply
	conn.SetReadDeadline(time.Now().Add(5 * time.Second))
	replyMsg, err := ReadMessage(conn)
	if err != nil {
		return RequestVoteReply{}, err
	}

	if replyMsg.Type != MessageRequestVoteReply {
		return RequestVoteReply{}, fmt.Errorf("unexpected message type: %d", replyMsg.Type)
	}

	return DecodeRequestVoteReply(replyMsg.Data)
}

// SendAppendEntries sends an AppendEntries RPC to a peer
func (t *Transport) SendAppendEntries(to int64, args AppendEntriesArgs) (AppendEntriesReply, error) {
	addr := t.getPeerAddr(to)
	if addr == "" {
		return AppendEntriesReply{}, fmt.Errorf("peer %d not found", to)
	}

	conn, err := net.DialTimeout("tcp", addr, 2*time.Second)
	if err != nil {
		return AppendEntriesReply{}, err
	}
	defer conn.Close()

	// Send peer id
	peerIDBuf := make([]byte, 8)
	for i := 0; i < 8; i++ {
		peerIDBuf[i] = byte((t.id >> (8 * (7 - i))) & 0xFF)
	}
	if _, err := conn.Write(peerIDBuf); err != nil {
		return AppendEntriesReply{}, err
	}

	// Send request
	msg := &Message{
		Type: MessageAppendEntries,
		Data: EncodeAppendEntries(args),
	}
	conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
	if err := WriteMessage(conn, msg); err != nil {
		return AppendEntriesReply{}, err
	}

	// Read reply
	conn.SetReadDeadline(time.Now().Add(5 * time.Second))
	replyMsg, err := ReadMessage(conn)
	if err != nil {
		return AppendEntriesReply{}, err
	}

	if replyMsg.Type != MessageAppendEntriesReply {
		return AppendEntriesReply{}, fmt.Errorf("unexpected message type: %d", replyMsg.Type)
	}

	return DecodeAppendEntriesReply(replyMsg.Data)
}

// getPeerAddr returns the address of a peer
func (t *Transport) getPeerAddr(id int64) string {
	t.mu.RLock()
	defer t.mu.RUnlock()
	return t.peers[id]
}

// Close closes the transport
func (t *Transport) Close() error {
	return t.listener.Close()
}

