package raft

import (
	"bytes"
	"testing"
)

func TestEncodeDecodeRequestVote(t *testing.T) {
	args := RequestVoteArgs{
		Term:         5,
		CandidateID:  2,
		LastLogIndex: 10,
		LastLogTerm:  4,
	}

	encoded := EncodeRequestVote(args)
	decoded, err := DecodeRequestVote(encoded)

	if err != nil {
		t.Errorf("Failed to decode: %v", err)
	}
	if decoded.Term != args.Term || decoded.CandidateID != args.CandidateID ||
		decoded.LastLogIndex != args.LastLogIndex || decoded.LastLogTerm != args.LastLogTerm {
		t.Errorf("Mismatch: got %+v, want %+v", decoded, args)
	}
}

func TestEncodeDecodeRequestVoteReply(t *testing.T) {
	reply := RequestVoteReply{
		Term:        5,
		VoteGranted: true,
	}

	encoded := EncodeRequestVoteReply(reply)
	decoded, err := DecodeRequestVoteReply(encoded)

	if err != nil {
		t.Errorf("Failed to decode: %v", err)
	}
	if decoded.Term != reply.Term || decoded.VoteGranted != reply.VoteGranted {
		t.Errorf("Mismatch: got %+v, want %+v", decoded, reply)
	}
}

func TestEncodeDecodeAppendEntries(t *testing.T) {
	args := AppendEntriesArgs{
		Term:         3,
		LeaderID:     1,
		PrevLogIndex: 5,
		PrevLogTerm:  2,
		Entries: []LogEntry{
			{Term: 3, Index: 6, Command: []byte("cmd1")},
			{Term: 3, Index: 7, Command: []byte("cmd2")},
		},
		LeaderCommit: 5,
	}

	encoded := EncodeAppendEntries(args)
	decoded, err := DecodeAppendEntries(encoded)

	if err != nil {
