package lsm

import (
	"fmt"
	"math"
	"math/rand"
	"sync"
)

const (
	// MaxLevel is the maximum level a node can have
	MaxLevel = 16
	// Probability is the probability of promoting a node to the next level
	Probability = 0.5
)

// Node represents a single node in the skiplist
type Node struct {
	key   []byte
	value []byte
	next  []*Node
	width []int64 // Width of each level (for rank-based operations)
}

// SkipList is a probabilistic data structure for storing sorted key-value pairs
type SkipList struct {
	head   *Node
	level  int
	size   int64
	mu     sync.RWMutex
	rng    *rand.Rand
}

// NewSkipList creates a new skiplist
func NewSkipList() *SkipList {
	head := &Node{
		next:  make([]*Node, MaxLevel),
		width: make([]int64, MaxLevel),
	}

	return &SkipList{
		head:  head,
		level: 0,
		size:  0,
		rng:   rand.New(rand.NewSource(rand.Int63())),
	}
}

// randomLevel returns a random level for a new node
func (sl *SkipList) randomLevel() int {
	level := 0
	for level < MaxLevel-1 && sl.rng.Float64() < Probability {
		level++
	}
	return level
}

// Put inserts or updates a key-value pair
func (sl *SkipList) Put(key, value []byte) {
	sl.mu.Lock()
	defer sl.mu.Unlock()

	if len(key) == 0 {
		return
	}

	// Find position to insert
	update := make([]*Node, MaxLevel)
	updateWidth := make([]int64, MaxLevel)
	rank := make([]int64, MaxLevel)

	x := sl.head
	rankCounter := int64(0)

	for i := sl.level; i >= 0; i-- {
		rankCounter += updateWidth[i]
		for x.next[i] != nil && compare(x.next[i].key, key) < 0 {
			rankCounter += x.width[i]
			x = x.next[i]
		}
		update[i] = x
		rank[i] = rankCounter
	}

	// Check if key already exists
	x = x.next[0]
	if x != nil && compare(x.key, key) == 0 {
		x.value = value
		return
	}

	// Insert new node
	level := sl.randomLevel()

	if level > sl.level {
		for i := sl.level + 1; i <= level; i++ {
			rank[i] = 0
			update[i] = sl.head
			update[i].width[i] = int64(sl.size) + 1
		}
		sl.level = level
	}

	newNode := &Node{
		key:   append([]byte{}, key...),
		value: append([]byte{}, value...),
		next:  make([]*Node, level+1),
		width: make([]int64, level+1),
	}

	for i := 0; i <= level; i++ {
		newNode.next[i] = update[i].next[i]
		update[i].next[i] = newNode

		newNode.width[i] = update[i].width[i] - (rank[0] - rank[i])
		update[i].width[i] = (rank[0] - rank[i]) + 1
	}

	for i := level + 1; i <= sl.level; i++ {
		update[i].width[i]++
	}

	sl.size++
}

// Get retrieves the value for a key
func (sl *SkipList) Get(key []byte) ([]byte, bool) {
	sl.mu.RLock()
	defer sl.mu.RUnlock()

	if len(key) == 0 {
		return nil, false
	}

	x := sl.head

	for i := sl.level; i >= 0; i-- {
		for x.next[i] != nil && compare(x.next[i].key, key) < 0 {
			x = x.next[i]
		}
	}

	x = x.next[0]
	if x != nil && compare(x.key, key) == 0 {
		return x.value, true
	}

	return nil, false
}

// Delete removes a key from the skiplist
func (sl *SkipList) Delete(key []byte) bool {
	sl.mu.Lock()
	defer sl.mu.Unlock()

	if len(key) == 0 {
		return false
	}

	update := make([]*Node, MaxLevel)
	x := sl.head

	for i := sl.level; i >= 0; i-- {
		for x.next[i] != nil && compare(x.next[i].key, key) < 0 {
			x = x.next[i]
		}
		update[i] = x
	}

	x = x.next[0]
	if x == nil || compare(x.key, key) != 0 {
		return false
	}

	for i := 0; i <= sl.level; i++ {
		if update[i].next[i] != x {
			break
		}
		update[i].next[i] = x.next[i]
		update[i].width[i] += x.width[i] - 1
	}

	for i := sl.level; i >= 0 && update[i].next[i] == nil; i-- {
		sl.level--
	}

	sl.size--
	return true
}

// Range returns all entries in the range [startKey, endKey)
func (sl *SkipList) Range(startKey, endKey []byte) []*Entry {
	sl.mu.RLock()
	defer sl.mu.RUnlock()

	var result []*Entry

	x := sl.head

	// Find the starting node
	for i := sl.level; i >= 0; i-- {
		for x.next[i] != nil && compare(x.next[i].key, startKey) < 0 {
			x = x.next[i]
		}
	}

	x = x.next[0]

	// Collect entries in range
	for x != nil && (len(endKey) == 0 || compare(x.key, endKey) < 0) {
		result = append(result, &Entry{
			Key:   append([]byte{}, x.key...),
			Value: append([]byte{}, x.value...),
		})
		x = x.next[0]
	}

	return result
}

// Size returns the number of entries in the skiplist
func (sl *SkipList) Size() int64 {
	sl.mu.RLock()
	defer sl.mu.RUnlock()
	return sl.size
}

// IsEmpty returns true if the skiplist is empty
func (sl *SkipList) IsEmpty() bool {
	sl.mu.RLock()
	defer sl.mu.RUnlock()
	return sl.size == 0
}

// ForEach calls a function for each entry in the skiplist
func (sl *SkipList) ForEach(fn func(*Entry) bool) {
	sl.mu.RLock()
	defer sl.mu.RUnlock()

	x := sl.head.next[0]
	for x != nil {
		entry := &Entry{
			Key:   x.key,
			Value: x.value,
		}
		if !fn(entry) {
			break
		}
		x = x.next[0]
	}
}

// GetMaxLevel returns the current maximum level
func (sl *SkipList) GetMaxLevel() int {
	sl.mu.RLock()
	defer sl.mu.RUnlock()
	return sl.level
}

// String returns a string representation of the skiplist
func (sl *SkipList) String() string {
	sl.mu.RLock()
	defer sl.mu.RUnlock()

	return fmt.Sprintf("SkipList(size=%d, maxLevel=%d)", sl.size, sl.level)
}

// compare compares two byte slices
// returns: < 0 if a < b, 0 if a == b, > 0 if a > b
func compare(a, b []byte) int {
	return bytesCompare(a, b)
}

// bytesCompare is a standard byte slice comparison
func bytesCompare(a, b []byte) int {
	minLen := len(a)
	if len(b) < minLen {
		minLen = len(b)
	}

	for i := 0; i < minLen; i++ {
		if a[i] < b[i] {
			return -1
		}
		if a[i] > b[i] {
			return 1
		}
	}

	if len(a) < len(b) {
		return -1
	}
	if len(a) > len(b) {
		return 1
	}
	return 0
}

// Entry represents a key-value entry
type Entry struct {
	Key   []byte
	Value []byte
}

// Rank returns the rank (position) of a key in the skiplist
func (sl *SkipList) Rank(key []byte) (int64, bool) {
	sl.mu.RLock()
	defer sl.mu.RUnlock()

	if len(key) == 0 {
		return 0, false
	}

	rankCounter := int64(0)
	x := sl.head

	for i := sl.level; i >= 0; i-- {
		for x.next[i] != nil && compare(x.next[i].key, key) < 0 {
			rankCounter += x.width[i]
			x = x.next[i]
		}
	}

	x = x.next[0]
	if x != nil && compare(x.key, key) == 0 {
		return rankCounter + 1, true
	}

	return 0, false
}

// RangeByRank returns entries from rank1 to rank2 (1-indexed, inclusive)
func (sl *SkipList) RangeByRank(rank1, rank2 int64) []*Entry {
	sl.mu.RLock()
	defer sl.mu.RUnlock()

	var result []*Entry

	if rank1 > rank2 || rank1 < 1 {
		return result
	}

	if rank2 > sl.size {
		rank2 = sl.size
	}

	rankCounter := int64(0)
	x := sl.head

	// Find the starting node
	for i := sl.level; i >= 0; i-- {
		for x.next[i] != nil && rankCounter+x.width[i] < rank1 {
			rankCounter += x.width[i]
			x = x.next[i]
		}
	}

	x = x.next[0]
	rankCounter++

	// Collect entries from rank1 to rank2
	for x != nil && rankCounter <= rank2 {
		result = append(result, &Entry{
			Key:   append([]byte{}, x.key...),
			Value: append([]byte{}, x.value...),
		})
		rankCounter++
		x = x.next[0]
	}

	return result
}

// ApproximateMemoryUsage returns an approximation of memory usage in bytes
func (sl *SkipList) ApproximateMemoryUsage() int64 {
	sl.mu.RLock()
	defer sl.mu.RUnlock()

	var usage int64

	x := sl.head.next[0]
	for x != nil {
		// Node pointer (8 bytes) + key + value + next pointers + width
		usage += 8 + int64(len(x.key)) + int64(len(x.value)) + int64((len(x.next)+len(x.width))*8)
		x = x.next[0]
	}

	// Head node
	usage += 8 + int64((MaxLevel+MaxLevel)*8)

	return usage
