package lsm

import (
	"bytes"
	"testing"
)

func TestSkipListBasic(t *testing.T) {
	sl := NewSkipList()

	sl.Put([]byte("key1"), []byte("value1"))
	sl.Put([]byte("key2"), []byte("value2"))
	sl.Put([]byte("key3"), []byte("value3"))

	if sl.Size() != 3 {
		t.Errorf("Expected size 3, got %d", sl.Size())
	}

	val, ok := sl.Get([]byte("key2"))
	if !ok || !bytes.Equal(val, []byte("value2")) {
		t.Errorf("Expected value2, got %v", val)
	}
}

func TestSkipListUpdate(t *testing.T) {
	sl := NewSkipList()

	sl.Put([]byte("key1"), []byte("value1"))
	sl.Put([]byte("key1"), []byte("updated"))

	if sl.Size() != 1 {
		t.Errorf("Expected size 1, got %d", sl.Size())
	}

	val, ok := sl.Get([]byte("key1"))
	if !ok || !bytes.Equal(val, []byte("updated")) {
		t.Errorf("Expected updated, got %v", val)
	}
}

func TestSkipListDelete(t *testing.T) {
	sl := NewSkipList()

	sl.Put([]byte("key1"), []byte("value1"))
	sl.Put([]byte("key2"), []byte("value2"))

	if !sl.Delete([]byte("key1")) {
		t.Error("Failed to delete key1")
	}

	if sl.Size() != 1 {
		t.Errorf("Expected size 1, got %d", sl.Size())
	}

	_, ok := sl.Get([]byte("key1"))
	if ok {
		t.Error("Expected key1 to be deleted")
	}
}

func TestSkipListRange(t *testing.T) {
	sl := NewSkipList()

	keys := []string{"a", "b", "c", "d", "e"}
	for i, key := range keys {
		sl.Put([]byte(key), []byte{byte(i)})
	}

	entries := sl.Range([]byte("b"), []byte("e"))
	if len(entries) != 3 {
		t.Errorf("Expected 3 entries, got %d", len(entries))
	}

	expected := []string{"b", "c", "d"}
	for i, exp := range expected {
		if !bytes.Equal(entries[i].Key, []byte(exp)) {
			t.Errorf("Entry %d: expected %s, got %s", i, exp, entries[i].Key)
		}
	}
}

func TestSkipListEmpty(t *testing.T) {
	sl := NewSkipList()

	if !sl.IsEmpty() {
		t.Error("Expected empty skiplist")
	}

	sl.Put([]byte("key"), []byte("value"))
	if sl.IsEmpty() {
		t.Error("Expected non-empty skiplist")
	}
}

func TestSkipListRank(t *testing.T) {
	sl := NewSkipList()

	keys := []string{"apple", "banana", "cherry", "date"}
	for _, key := range keys {
		sl.Put([]byte(key), []byte("value"))
	}

	rank, ok := sl.Rank([]byte("banana"))
	if !ok || rank != 2 {
		t.Errorf("Expected rank 2 for banana, got %d", rank)
	}

	rank, ok = sl.Rank([]byte("date"))
	if !ok || rank != 4 {
		t.Errorf("Expected rank 4 for date, got %d", rank)
	}
}

func TestSkipListRangeByRank(t *testing.T) {
	sl := NewSkipList()

	keys := []string{"a", "b", "c", "d", "e"}
	for _, key := range keys {
		sl.Put([]byte(key), []byte("value"))
	}

	entries := sl.RangeByRank(2, 4)
	if len(entries) != 3 {
		t.Errorf("Expected 3 entries, got %d", len(entries))
	}

	expected := []string{"b", "c", "d"}
	for i, exp := range expected {
		if !bytes.Equal(entries[i].Key, []byte(exp)) {
			t.Errorf("Entry %d: expected %s, got %s", i, exp, entries[i].Key)
		}
	}
}

func TestSkipListConcurrency(t *testing.T) {
	sl := NewSkipList()

	// Write from 10 goroutines
	done := make(chan bool, 10)
	for g := 0; g < 10; g++ {
		go func(id int) {
			for i := 0; i < 100; i++ {
				key := []byte{byte(id), byte(i)}
				sl.Put(key, []byte("value"))
			}
			done <- true
		}(g)
	}

	// Wait for all goroutines
	for i := 0; i < 10; i++ {
		<-done
	}

	if sl.Size() != 1000 {
		t.Errorf("Expected size 1000, got %d", sl.Size())
	}
}

func TestSkipListMemoryUsage(t *testing.T) {
	sl := NewSkipList()

	for i := 0; i < 100; i++ {
		key := []byte{byte(i / 256), byte(i % 256)}
		sl.Put(key, make([]byte, 100))
	}

	mem := sl.ApproximateMemoryUsage()
	if mem < 1000 {
		t.Errorf("Memory usage seems too low: %d", mem)
	}
}

func TestSkipListLevel(t *testing.T) {
	sl := NewSkipList()

	for i := 0; i < 100; i++ {
		key := []byte{byte(i / 256), byte(i % 256)}
		sl.Put(key, []byte("value"))
	}

	level := sl.GetMaxLevel()
	if level == 0 {
		t.Errorf("Expected level > 0 after 100 insertions, got %d", level)
	}

	if level >= MaxLevel {
		t.Errorf("Level %d exceeds MaxLevel %d", level, MaxLevel)
	}
}

func TestSkipListNonExistent(t *testing.T) {
	sl := NewSkipList()

	sl.Put([]byte("a"), []byte("1"))
	sl.Put([]byte("c"), []byte("3"))

	_, ok := sl.Get([]byte("b"))
	if ok {
		t.Error("Expected key b to not exist")
	}
}

func TestSkipListForEach(t *testing.T) {
	sl := NewSkipList()

	keys := []string{"a", "b", "c"}
	for _, key := range keys {
		sl.Put([]byte(key), []byte("value"))
	}

	count := 0
	sl.ForEach(func(entry *Entry) bool {
		count++
		return true
	})

	if count != 3 {
		t.Errorf("Expected 3 entries, got %d", count)
	}
}

func TestSkipListOrdering(t *testing.T) {
	sl := NewSkipList()

	// Insert in random order
	keys := []string{"zebra", "apple", "monkey", "banana"}
	for _, key := range keys {
		sl.Put([]byte(key), []byte("value"))
	}

	// Should be returned in sorted order
	var result []string
	sl.ForEach(func(entry *Entry) bool {
		result = append(result, string(entry.Key))
		return true
	})

	expected := []string{"apple", "banana", "monkey", "zebra"}
	for i, exp := range expected {
		if result[i] != exp {
			t.Errorf("Position %d: expected %s, got %s", i, exp, result[i])
		}
	}
}

func BenchmarkSkipListInsert(b *testing.B) {
	sl := NewSkipList()

	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		key := []byte{byte(i / 65536), byte((i / 256) % 256), byte(i % 256)}
		sl.Put(key, []byte("value"))
	}
}

func BenchmarkSkipListGet(b *testing.B) {
	sl := NewSkipList()

	for i := 0; i < 10000; i++ {
		key := []byte{byte(i / 256), byte(i % 256)}
		sl.Put(key, []byte("value"))
	}

	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		key := []byte{byte(i % 256), byte((i / 256) % 256)}
		sl.Get(key)
	}
}

