func TestSkipListMemoryUsage(t *testing.T) {
	sl := NewSkipList()

	for i := 0; i < 100; i++ {
		key := []byte{byte(i / 256), byte(i % 256)}
		sl.Put(key, make([]byte, 100))
	}

	mem := sl.ApproximateMemoryUsage()
	if mem < 1000 {
		t.Errorf("Memory usage seems too low: %d", mem)
	}
}

func TestSkipListLevel(t *testing.T) {
	sl := NewSkipList()

	for i := 0; i < 100; i++ {
		key := []byte{byte(i / 256), byte(i % 256)}
		sl.Put(key, []byte("value"))
	}

	level := sl.GetMaxLevel()
	if level == 0 {
		t.Errorf("Expected level > 0 after 100 insertions, got %d", level)
	}

	if level >= MaxLevel {
		t.Errorf("Level %d exceeds MaxLevel %d", level, MaxLevel)
	}
}

func TestSkipListNonExistent(t *testing.T) {
	sl := NewSkipList()

	sl.Put([]byte("a"), []byte("1"))
	sl.Put([]byte("c"), []byte("3"))

	_, ok := sl.Get([]byte("b"))
	if ok {
		t.Error("Expected key b to not exist")
	}
}

func TestSkipListForEach(t *testing.T) {
	sl := NewSkipList()

	keys := []string{"a", "b", "c"}
	for _, key := range keys {
		sl.Put([]byte(key), []byte("value"))
	}

	count := 0
	sl.ForEach(func(entry *Entry) bool {
		count++
		return true
	})

	if count != 3 {
		t.Errorf("Expected 3 entries, got %d", count)
	}
}

func TestSkipListOrdering(t *testing.T) {
	sl := NewSkipList()

	// Insert in random order
	keys := []string{"zebra", "apple", "monkey", "banana"}
	for _, key := range keys {
		sl.Put([]byte(key), []byte("value"))
	}

	// Should be returned in sorted order
	var result []string
	sl.ForEach(func(entry *Entry) bool {
		result = append(result, string(entry.Key))
		return true
	})

	expected := []string{"apple", "banana", "monkey", "zebra"}
	for i, exp := range expected {
		if result[i] != exp {
			t.Errorf("Position %d: expected %s, got %s", i, exp, result[i])
		}
	}
}

func BenchmarkSkipListInsert(b *testing.B) {
	sl := NewSkipList()

	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		key := []byte{byte(i / 65536), byte((i / 256) % 256), byte(i % 256)}
		sl.Put(key, []byte("value"))
	}
}

func BenchmarkSkipListGet(b *testing.B) {
	sl := NewSkipList()

	for i := 0; i < 10000; i++ {
		key := []byte{byte(i / 256), byte(i % 256)}
		sl.Put(key, []byte("value"))
	}

	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		key := []byte{byte(i % 256), byte((i / 256) % 256)}
		sl.Get(key)
	}
}

