package iac

import (
	"fmt"
	"unicode"
)

// Lexer tokenizes HCL source code
type Lexer struct {
	input  string
	pos    int  // current position
	line   int  // current line
	col    int  // current column
	tokens []Token
}

// NewLexer creates a new lexer
func NewLexer(input string) *Lexer {
	return &Lexer{
		input: input,
		pos:   0,
		line:  1,
		col:   1,
	}
}

// Lex tokenizes the input and returns a list of tokens
func (l *Lexer) Lex() ([]Token, error) {
	for l.pos < len(l.input) {
		ch := l.current()

		switch {
		case ch == '\n':
			l.addToken(TokenNewline, "\n")
			l.advance()
			l.line++
			l.col = 1

		case ch == ' ' || ch == '\t' || ch == '\r':
			l.skipWhitespace()

		case ch == '#':
			l.skipComment()

		case ch == '"':
			l.lexString()

		case ch == '=':
			if l.peek() == '>' {
				l.addToken(TokenArrow, "=>")
				l.advance()
				l.advance()
			} else {
				l.addToken(TokenEqual, "=")
				l.advance()
			}

		case ch == '{':
			l.addToken(TokenLBrace, "{")
			l.advance()

		case ch == '}':
			l.addToken(TokenRBrace, "}")
			l.advance()

		case ch == '[':
			l.addToken(TokenLBracket, "[")
			l.advance()

		case ch == ']':
			l.addToken(TokenRBracket, "]")
			l.advance()

		case ch == '(':
			l.addToken(TokenLParen, "(")
			l.advance()

		case ch == ')':
			l.addToken(TokenRParen, ")")
			l.advance()

		case ch == ',':
			l.addToken(TokenComma, ",")
			l.advance()

		case ch == ':':
			l.addToken(TokenColon, ":")
			l.advance()

		case ch == '.':
			l.addToken(TokenDot, ".")
			l.advance()

		case ch == '?':
			l.addToken(TokenQuestion, "?")
			l.advance()

		case unicode.IsDigit(rune(ch)) || (ch == '-' && unicode.IsDigit(rune(l.peek()))):
			l.lexNumber()

		case unicode.IsLetter(rune(ch)) || ch == '_':
			l.lexIdentOrKeyword()

		default:
			return nil, fmt.Errorf("unexpected character: %c at line %d, col %d", ch, l.line, l.col)
		}
	}

	l.addToken(TokenEOF, "")
	return l.tokens, nil
}

// current returns the current character
func (l *Lexer) current() byte {
	if l.pos >= len(l.input) {
		return 0
	}
	return l.input[l.pos]
}

// peek returns the next character without advancing
func (l *Lexer) peek() byte {
	if l.pos+1 >= len(l.input) {
		return 0
	}
	return l.input[l.pos+1]
}

// advance moves to the next character
func (l *Lexer) advance() {
	if l.pos < len(l.input) {
		l.pos++
		l.col++
	}
}

// addToken adds a token to the list
func (l *Lexer) addToken(tt TokenType, value string) {
	l.tokens = append(l.tokens, Token{
		Type:  tt,
		Value: value,
		Line:  l.line,
		Col:   l.col,
	})
}

// skipWhitespace skips whitespace characters
func (l *Lexer) skipWhitespace() {
	for l.pos < len(l.input) && (l.current() == ' ' || l.current() == '\t' || l.current() == '\r') {
		l.advance()
	}
}

// skipComment skips a comment line
func (l *Lexer) skipComment() {
	for l.pos < len(l.input) && l.current() != '\n' {
		l.advance()
	}
}

// lexString reads a string literal
func (l *Lexer) lexString() {
	l.advance() // skip opening quote

	start := l.pos
	for l.pos < len(l.input) && l.current() != '"' {
		if l.current() == '\\' {
			l.advance()
		}
		if l.current() != '\n' {
			l.advance()
		}
	}

	value := l.input[start : l.pos]

	if l.pos >= len(l.input) {
		l.addToken(TokenError, "unterminated string")
		return
	}

	l.advance() // skip closing quote
	l.addToken(TokenString, value)
}

// lexNumber reads a number literal
func (l *Lexer) lexNumber() {
	start := l.pos

	// Handle negative sign
	if l.current() == '-' {
		l.advance()
	}

	// Read digits
	for l.pos < len(l.input) && unicode.IsDigit(rune(l.current())) {
		l.advance()
	}

	// Read decimal part
	if l.current() == '.' && unicode.IsDigit(rune(l.peek())) {
		l.advance()
		for l.pos < len(l.input) && unicode.IsDigit(rune(l.current())) {
			l.advance()
		}
	}

	value := l.input[start:l.pos]
	l.addToken(TokenNumber, value)
}

// lexIdentOrKeyword reads an identifier or keyword
func (l *Lexer) lexIdentOrKeyword() {
	start := l.pos

	for l.pos < len(l.input) && (unicode.IsLetter(rune(l.current())) || unicode.IsDigit(rune(l.current())) || l.current() == '_' || l.current() == '-') {
		l.advance()
	}

	value := l.input[start:l.pos]

	// Check if it's a keyword
	if tt, ok := IsKeyword(value); ok {
		l.addToken(tt, value)
	} else {
		l.addToken(TokenIdent, value)
	}
}

