		l.advance()
	}

	// Read digits
	for l.pos < len(l.input) && unicode.IsDigit(rune(l.current())) {
		l.advance()
	}

	// Read decimal part
	if l.current() == '.' && unicode.IsDigit(rune(l.peek())) {
		l.advance()
		for l.pos < len(l.input) && unicode.IsDigit(rune(l.current())) {
			l.advance()
		}
	}

	value := l.input[start:l.pos]
	l.addToken(TokenNumber, value)
}

// lexIdentOrKeyword reads an identifier or keyword
func (l *Lexer) lexIdentOrKeyword() {
	start := l.pos

	for l.pos < len(l.input) && (unicode.IsLetter(rune(l.current())) || unicode.IsDigit(rune(l.current())) || l.current() == '_' || l.current() == '-') {
		l.advance()
	}

	value := l.input[start:l.pos]

	// Check if it's a keyword
	if tt, ok := IsKeyword(value); ok {
		l.addToken(tt, value)
	} else {
		l.addToken(TokenIdent, value)
	}
}

