package lsm

import (
	"encoding/binary"
	"fmt"
	"os"
	"sync"
)

// WALEntry represents a single entry in the write-ahead log
type WALEntry struct {
	Type  EntryType
	Key   []byte
	Value []byte
}

// EntryType represents the type of operation
type EntryType uint8

const (
	EntryTypePut EntryType = iota + 1
	EntryTypeDelete
	EntryTypeSync
)

// WAL (Write-Ahead Log) ensures durability
type WAL struct {
	file       *os.File
	path       string
	entries    int64
	size       int64
	maxSize    int64 // Maximum file size before rotation
	mu         sync.Mutex
	buffer     []byte
	bufferPos  int
}

// NewWAL creates a new write-ahead log
func NewWAL(path string, maxSize int64) (*WAL, error) {
	// Open or create file
	file, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0644)
	if err != nil {
		return nil, fmt.Errorf("failed to open WAL file: %w", err)
	}

	// Get current file size
	stat, err := file.Stat()
	if err != nil {
		file.Close()
		return nil, fmt.Errorf("failed to stat WAL file: %w", err)
	}

	return &WAL{
		file:      file,
		path:      path,
		size:      stat.Size(),
		maxSize:   maxSize,
		buffer:    make([]byte, 65536), // 64KB buffer
		bufferPos: 0,
	}, nil
}

// Write writes an entry to the WAL
func (w *WAL) Write(entry *WALEntry) error {
	w.mu.Lock()
	defer w.mu.Unlock()

	// Encode entry
	encoded := encodeWALEntry(entry)

	// Check if we need to flush buffer
	if w.bufferPos+len(encoded) > len(w.buffer) {
		if err := w.flush(); err != nil {
			return err
		}
	}

	// Copy to buffer
	copy(w.buffer[w.bufferPos:], encoded)
	w.bufferPos += len(encoded)
	w.size += int64(len(encoded))
	w.entries++

	// Check if file should be rotated
	if w.size > w.maxSize {
		return w.rotate()
	}

	return nil
}

// Sync flushes the buffer to disk
func (w *WAL) Sync() error {
	w.mu.Lock()
	defer w.mu.Unlock()

	if err := w.flush(); err != nil {
		return err
	}

	return w.file.Sync()
}

// flush writes buffer to disk
func (w *WAL) flush() error {
	if w.bufferPos == 0 {
		return nil
	}

	_, err := w.file.Write(w.buffer[:w.bufferPos])
	if err != nil {
		return fmt.Errorf("failed to write to WAL: %w", err)
	}

	w.bufferPos = 0
	return nil
}

// rotate creates a new WAL file
func (w *WAL) rotate() error {
	if err := w.flush(); err != nil {
		return err
	}

	// Close current file
	if err := w.file.Close(); err != nil {
		return fmt.Errorf("failed to close WAL file: %w", err)
	}

	// Create new filename with timestamp
	newPath := fmt.Sprintf("%s.%d", w.path, w.entries)

	// Rename current file
	if err := os.Rename(w.path, newPath); err != nil {
		return fmt.Errorf("failed to rotate WAL file: %w", err)
	}

	// Open new WAL file
	file, err := os.OpenFile(w.path, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0644)
	if err != nil {
		return fmt.Errorf("failed to create new WAL file: %w", err)
	}

	w.file = file
	w.size = 0

	return nil
}

// Close closes the WAL
func (w *WAL) Close() error {
	w.mu.Lock()
	defer w.mu.Unlock()

	if err := w.flush(); err != nil {
		return err
	}

	if err := w.file.Sync(); err != nil {
		return err
	}

	return w.file.Close()
}

// Recover reads the WAL and returns all entries
func (w *WAL) Recover() ([]*WALEntry, error) {
	w.mu.Lock()
	defer w.mu.Unlock()

	// Close current file for reading
	if err := w.file.Close(); err != nil {
		return nil, fmt.Errorf("failed to close WAL file: %w", err)
	}

	// Open for reading
	file, err := os.Open(w.path)
	if err != nil {
		// Reopen for writing
		f, _ := os.OpenFile(w.path, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0644)
		w.file = f
		return []*WALEntry{}, nil
	}
	defer file.Close()

	var entries []*WALEntry
	buffer := make([]byte, 65536)

	for {
		n, err := file.Read(buffer)
		if n == 0 || err != nil {
			break
		}

		// Decode entries from buffer
		offset := 0
		for offset < n {
			entry, bytesRead, err := decodeWALEntry(buffer[offset:n])
			if err != nil {
				break
			}
			entries = append(entries, entry)
			offset += bytesRead
		}
	}

	// Reopen for writing
	f, err := os.OpenFile(w.path, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0644)
	if err != nil {
		return nil, fmt.Errorf("failed to reopen WAL file: %w", err)
	}
	w.file = f

	return entries, nil
}

// encodeWALEntry encodes a WAL entry to bytes
func encodeWALEntry(entry *WALEntry) []byte {
	// Format:
	// [1 byte: type][4 bytes: key length][4 bytes: value length][key][value]

	keyLen := len(entry.Key)
	valueLen := len(entry.Value)
	totalLen := 1 + 4 + 4 + keyLen + valueLen

	buf := make([]byte, totalLen)
	pos := 0

	// Type
	buf[pos] = byte(entry.Type)
	pos++

	// Key length
	binary.BigEndian.PutUint32(buf[pos:pos+4], uint32(keyLen))
	pos += 4

	// Value length
	binary.BigEndian.PutUint32(buf[pos:pos+4], uint32(valueLen))
	pos += 4

	// Key
	copy(buf[pos:pos+keyLen], entry.Key)
	pos += keyLen

	// Value
	copy(buf[pos:pos+valueLen], entry.Value)

	return buf
}

// decodeWALEntry decodes a WAL entry from bytes
func decodeWALEntry(buf []byte) (*WALEntry, int, error) {
	if len(buf) < 9 {
		return nil, 0, fmt.Errorf("buffer too small")
	}

	pos := 0

	// Type
	entryType := EntryType(buf[pos])
	pos++

	// Key length
	keyLen := binary.BigEndian.Uint32(buf[pos : pos+4])
	pos += 4

	// Value length
	valueLen := binary.BigEndian.Uint32(buf[pos : pos+4])
	pos += 4

	// Check if buffer has enough data
	totalLen := pos + int(keyLen) + int(valueLen)
	if len(buf) < totalLen {
		return nil, 0, fmt.Errorf("buffer too small for entry")
	}

	// Key
	key := make([]byte, keyLen)
	copy(key, buf[pos:pos+int(keyLen)])
	pos += int(keyLen)

	// Value
	value := make([]byte, valueLen)
	copy(value, buf[pos:pos+int(valueLen)])
	pos += int(valueLen)

	entry := &WALEntry{
		Type:  entryType,
		Key:   key,
		Value: value,
	}

	return entry, totalLen, nil
}

// GetSize returns the current WAL file size
func (w *WAL) GetSize() int64 {
	w.mu.Lock()
	defer w.mu.Unlock()
	return w.size
}

// GetEntryCount returns the number of entries in the WAL
func (w *WAL) GetEntryCount() int64 {
	w.mu.Lock()
	defer w.mu.Unlock()
	return w.entries
}

