	wal, err := NewWAL(tmpfile.Name(), 1024*1024)
	if err != nil {
		t.Fatalf("Failed to create WAL: %v", err)
	}

	entries := []*WALEntry{
		{Type: EntryTypePut, Key: []byte("key1"), Value: []byte("value1")},
		{Type: EntryTypePut, Key: []byte("key2"), Value: []byte("value2")},
	}

	for _, entry := range entries {
		if err := wal.Write(entry); err != nil {
			t.Fatalf("Failed to write entry: %v", err)
		}
	}

