	// Recover entries
	wal2, err := NewWAL(tmpfile.Name(), 1024*1024)
	if err != nil {
		t.Fatalf("Failed to create WAL for recovery: %v", err)
	}
	defer wal2.Close()

	recovered, err := wal2.Recover()
	if err != nil {
		t.Fatalf("Failed to recover: %v", err)
	}

	if len(recovered) != 2 {
		t.Errorf("Expected 2 entries, got %d", len(recovered))
	}

