	defer wal.Close()

	// Write and sync
	entry := &WALEntry{Type: EntryTypePut, Key: []byte("test"), Value: []byte("data")}
	if err := wal.Write(entry); err != nil {
		t.Fatalf("Failed to write: %v", err)
	}

	if err := wal.Sync(); err != nil {
		t.Fatalf("Failed to sync: %v", err)
	}

	// Verify file was written
	stat, err := os.Stat(tmpfile.Name())
	if err != nil {
		t.Fatalf("Failed to stat file: %v", err)
	}

	if stat.Size() == 0 {
		t.Error("Expected non-empty WAL file")
	}
}

func TestWALEncoding(t *testing.T) {
	entry := &WALEntry{
		Type:  EntryTypePut,
		Key:   []byte("testkey"),
		Value: []byte("testvalue"),
	}

	// Encode
	encoded := encodeWALEntry(entry)

	// Decode
	decoded, bytesRead, err := decodeWALEntry(encoded)
	if err != nil {
		t.Fatalf("Failed to decode: %v", err)
	}

	if bytesRead != len(encoded) {
		t.Errorf("Expected bytes read %d, got %d", len(encoded), bytesRead)
	}

	if decoded.Type != entry.Type {
		t.Errorf("Type mismatch: expected %d, got %d", entry.Type, decoded.Type)
	}

	if !bytes.Equal(decoded.Key, entry.Key) {
		t.Errorf("Key mismatch: expected %s, got %s", entry.Key, decoded.Key)
	}

	if !bytes.Equal(decoded.Value, entry.Value) {
		t.Errorf("Value mismatch: expected %s, got %s", entry.Value, decoded.Value)
	}
}

func TestWALMultipleEntries(t *testing.T) {
	tmpfile, err := os.CreateTemp("", "wal_multiple_")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	defer os.Remove(tmpfile.Name())
	tmpfile.Close()

	wal, err := NewWAL(tmpfile.Name(), 1024*1024)
	if err != nil {
		t.Fatalf("Failed to create WAL: %v", err)
	}
	defer wal.Close()

	// Write 100 entries
	for i := 0; i < 100; i++ {
		key := []byte{byte(i / 256), byte(i % 256)}
		value := make([]byte, 100)
		entry := &WALEntry{Type: EntryTypePut, Key: key, Value: value}
		if err := wal.Write(entry); err != nil {
			t.Fatalf("Failed to write entry %d: %v", i, err)
		}
	}

	if wal.GetEntryCount() != 100 {
		t.Errorf("Expected 100 entries, got %d", wal.GetEntryCount())
	}
}

func TestWALDeleteEntry(t *testing.T) {
	tmpfile, err := os.CreateTemp("", "wal_delete_")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	defer os.Remove(tmpfile.Name())
	tmpfile.Close()

	wal, err := NewWAL(tmpfile.Name(), 1024*1024)
	if err != nil {
		t.Fatalf("Failed to create WAL: %v", err)
	}
	defer wal.Close()

	// Write put and delete
	putEntry := &WALEntry{Type: EntryTypePut, Key: []byte("key"), Value: []byte("value")}
	deleteEntry := &WALEntry{Type: EntryTypeDelete, Key: []byte("key"), Value: []byte{}}

	if err := wal.Write(putEntry); err != nil {
		t.Fatalf("Failed to write put: %v", err)
	}

	if err := wal.Write(deleteEntry); err != nil {
		t.Fatalf("Failed to write delete: %v", err)
	}

	if wal.GetEntryCount() != 2 {
		t.Errorf("Expected 2 entries, got %d", wal.GetEntryCount())
	}
}

