package lsm

import (
	"fmt"
	"sync"
	"time"
)

// MemTable represents an in-memory table with a SkipList
type MemTable struct {
	sl           *SkipList
	wal          *WAL
	size         int64
	maxSize      int64 // Max size before flushing to SSTable
	entries      int64
	createdTime  time.Time
	lastModified time.Time
	mu           sync.RWMutex
	isFrozen     bool
}

// NewMemTable creates a new MemTable
func NewMemTable(walPath string, maxSize int64) (*MemTable, error) {
	wal, err := NewWAL(walPath, maxSize*2)
	if err != nil {
		return nil, err
	}

	return &MemTable{
		sl:          NewSkipList(),
		wal:         wal,
		maxSize:     maxSize,
		createdTime: time.Now(),
	}, nil
}

// Put inserts or updates a key-value pair
func (m *MemTable) Put(key, value []byte) error {
	m.mu.Lock()
	defer m.mu.Unlock()

	if m.isFrozen {
		return fmt.Errorf("memtable is frozen")
	}

	// Write to WAL for durability
	entry := &WALEntry{
		Type:  EntryTypePut,
		Key:   key,
		Value: value,
	}

	if err := m.wal.Write(entry); err != nil {
		return err
	}

	// Add to SkipList
	m.sl.Put(key, value)

	// Update size
	m.size += int64(len(key) + len(value))
	m.entries++
	m.lastModified = time.Now()

	return nil
}

// Get retrieves the value for a key
func (m *MemTable) Get(key []byte) ([]byte, bool) {
	m.mu.RLock()
	defer m.mu.RUnlock()

	return m.sl.Get(key)
}

// Delete removes a key
func (m *MemTable) Delete(key []byte) error {
	m.mu.Lock()
	defer m.mu.Unlock()

	if m.isFrozen {
		return fmt.Errorf("memtable is frozen")
	}

	// Write to WAL
	entry := &WALEntry{
		Type:  EntryTypeDelete,
		Key:   key,
		Value: []byte{},
	}

	if err := m.wal.Write(entry); err != nil {
		return err
	}

	// Delete from SkipList
	if m.sl.Delete(key) {
		m.entries--
		m.lastModified = time.Now()
	}

	return nil
}

// Range returns entries in the specified range
func (m *MemTable) Range(startKey, endKey []byte) []*Entry {
	m.mu.RLock()
	defer m.mu.RUnlock()

	return m.sl.Range(startKey, endKey)
}

// Size returns the current memory size
func (m *MemTable) Size() int64 {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return m.size
}

// EntryCount returns the number of entries
func (m *MemTable) EntryCount() int64 {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return m.entries
}

// IsFull checks if the MemTable should be flushed
func (m *MemTable) IsFull() bool {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return m.size >= m.maxSize
}

// Freeze marks the MemTable as read-only
func (m *MemTable) Freeze() {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.isFrozen = true
}

// IsFrozen checks if the MemTable is read-only
func (m *MemTable) IsFrozen() bool {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return m.isFrozen
}

// GetEntries returns all entries in sorted order
func (m *MemTable) GetEntries() []*Entry {
	m.mu.RLock()
	defer m.mu.RUnlock()

	return m.sl.Range(nil, nil)
}

// Sync syncs the WAL to disk
func (m *MemTable) Sync() error {
	m.mu.Lock()
	defer m.mu.Unlock()

	return m.wal.Sync()
}

// Close closes the MemTable and WAL
func (m *MemTable) Close() error {
	m.mu.Lock()
	defer m.mu.Unlock()

	return m.wal.Close()
}

// GetCreatedTime returns when the MemTable was created
func (m *MemTable) GetCreatedTime() time.Time {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return m.createdTime
}

// GetLastModified returns the last modification time
func (m *MemTable) GetLastModified() time.Time {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return m.lastModified
}

// ApproximateMemoryUsage returns the approximate memory usage
func (m *MemTable) ApproximateMemoryUsage() int64 {
	m.mu.RLock()
	defer m.mu.RUnlock()

	return m.sl.ApproximateMemoryUsage()
}

// Clear empties the MemTable (for testing)
func (m *MemTable) Clear() {
	m.mu.Lock()
	defer m.mu.Unlock()

	m.sl = NewSkipList()
	m.size = 0
	m.entries = 0
	m.isFrozen = false
}

// ForEach iterates over all entries
func (m *MemTable) ForEach(fn func(*Entry) bool) {
	m.mu.RLock()
	defer m.mu.RUnlock()

	m.sl.ForEach(fn)
}

// GetMaxLevel returns the maximum SkipList level
func (m *MemTable) GetMaxLevel() int {
	m.mu.RLock()
	defer m.mu.RUnlock()

	return m.sl.GetMaxLevel()
}

