package lsm

import (
	"bytes"
	"os"
	"testing"
)

func TestMemTablePutGet(t *testing.T) {
	tmpfile, err := os.CreateTemp("", "memtable_test_")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	defer os.Remove(tmpfile.Name())
	tmpfile.Close()

	mt, err := NewMemTable(tmpfile.Name(), 1024*1024)
	if err != nil {
		t.Fatalf("Failed to create MemTable: %v", err)
	}
	defer mt.Close()

	// Put
	if err := mt.Put([]byte("key1"), []byte("value1")); err != nil {
		t.Fatalf("Failed to put: %v", err)
	}

	// Get
	val, ok := mt.Get([]byte("key1"))
	if !ok || !bytes.Equal(val, []byte("value1")) {
		t.Errorf("Expected value1, got %v", val)
	}

	if mt.EntryCount() != 1 {
		t.Errorf("Expected 1 entry, got %d", mt.EntryCount())
	}
}

func TestMemTableDelete(t *testing.T) {
	tmpfile, err := os.CreateTemp("", "memtable_delete_")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	defer os.Remove(tmpfile.Name())
	tmpfile.Close()

	mt, err := NewMemTable(tmpfile.Name(), 1024*1024)
	if err != nil {
		t.Fatalf("Failed to create MemTable: %v", err)
	}
	defer mt.Close()

	// Put and delete
	if err := mt.Put([]byte("key"), []byte("value")); err != nil {
		t.Fatalf("Failed to put: %v", err)
	}

	if err := mt.Delete([]byte("key")); err != nil {
		t.Fatalf("Failed to delete: %v", err)
	}

	_, ok := mt.Get([]byte("key"))
	if ok {
		t.Error("Expected key to be deleted")
	}

	if mt.EntryCount() != 0 {
		t.Errorf("Expected 0 entries, got %d", mt.EntryCount())
	}
}

func TestMemTableRange(t *testing.T) {
	tmpfile, err := os.CreateTemp("", "memtable_range_")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	defer os.Remove(tmpfile.Name())
	tmpfile.Close()

	mt, err := NewMemTable(tmpfile.Name(), 1024*1024)
	if err != nil {
		t.Fatalf("Failed to create MemTable: %v", err)
	}
	defer mt.Close()

	// Put multiple values
	keys := []string{"a", "b", "c", "d", "e"}
	for _, key := range keys {
		if err := mt.Put([]byte(key), []byte("value")); err != nil {
			t.Fatalf("Failed to put: %v", err)
		}
	}

	// Range query
	entries := mt.Range([]byte("b"), []byte("e"))
	if len(entries) != 3 {
		t.Errorf("Expected 3 entries, got %d", len(entries))
	}
}

func TestMemTableFrozen(t *testing.T) {
	tmpfile, err := os.CreateTemp("", "memtable_frozen_")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	defer os.Remove(tmpfile.Name())
	tmpfile.Close()

	mt, err := NewMemTable(tmpfile.Name(), 1024*1024)
	if err != nil {
		t.Fatalf("Failed to create MemTable: %v", err)
	}
	defer mt.Close()

	// Put before freezing
	if err := mt.Put([]byte("key1"), []byte("value1")); err != nil {
		t.Fatalf("Failed to put: %v", err)
	}

	// Freeze
	mt.Freeze()

	// Try to put after freezing
	if err := mt.Put([]byte("key2"), []byte("value2")); err == nil {
		t.Error("Expected error when putting to frozen MemTable")
	}

	// Get should still work
	val, ok := mt.Get([]byte("key1"))
	if !ok || !bytes.Equal(val, []byte("value1")) {
		t.Error("Get should work on frozen MemTable")
	}
}

func TestMemTableIsFull(t *testing.T) {
	tmpfile, err := os.CreateTemp("", "memtable_full_")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	defer os.Remove(tmpfile.Name())
	tmpfile.Close()

	// Create with small max size
	mt, err := NewMemTable(tmpfile.Name(), 100)
	if err != nil {
		t.Fatalf("Failed to create MemTable: %v", err)
	}
	defer mt.Close()

	// Put until full
	for i := 0; i < 10; i++ {
		key := []byte{byte(i)}
		value := make([]byte, 20)
		if err := mt.Put(key, value); err != nil {
			t.Fatalf("Failed to put: %v", err)
		}

		if mt.IsFull() {
			break
		}
	}

	if !mt.IsFull() {
		t.Error("Expected MemTable to be full")
	}
}

func TestMemTableSync(t *testing.T) {
	tmpfile, err := os.CreateTemp("", "memtable_sync_")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	defer os.Remove(tmpfile.Name())
	tmpfile.Close()

	mt, err := NewMemTable(tmpfile.Name(), 1024*1024)
	if err != nil {
		t.Fatalf("Failed to create MemTable: %v", err)
	}
	defer mt.Close()

	// Put and sync
	if err := mt.Put([]byte("key"), []byte("value")); err != nil {
		t.Fatalf("Failed to put: %v", err)
	}

	if err := mt.Sync(); err != nil {
		t.Fatalf("Failed to sync: %v", err)
	}

	// Verify file exists and has content
	stat, err := os.Stat(tmpfile.Name())
	if err != nil {
		t.Fatalf("Failed to stat file: %v", err)
	}

	if stat.Size() == 0 {
		t.Error("Expected WAL file to have content")
	}
}

func TestMemTableGetEntries(t *testing.T) {
	tmpfile, err := os.CreateTemp("", "memtable_entries_")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	defer os.Remove(tmpfile.Name())
	tmpfile.Close()

	mt, err := NewMemTable(tmpfile.Name(), 1024*1024)
	if err != nil {
		t.Fatalf("Failed to create MemTable: %v", err)
	}
	defer mt.Close()

	// Put entries
	for i := 0; i < 5; i++ {
		key := []byte{byte(i)}
		if err := mt.Put(key, []byte("value")); err != nil {
			t.Fatalf("Failed to put: %v", err)
		}
	}

	// Get all entries
	entries := mt.GetEntries()
	if len(entries) != 5 {
		t.Errorf("Expected 5 entries, got %d", len(entries))
	}
}

func TestMemTableApproximateMemoryUsage(t *testing.T) {
	tmpfile, err := os.CreateTemp("", "memtable_mem_")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	defer os.Remove(tmpfile.Name())
	tmpfile.Close()

	mt, err := NewMemTable(tmpfile.Name(), 1024*1024)
	if err != nil {
		t.Fatalf("Failed to create MemTable: %v", err)
	}
	defer mt.Close()

	// Put entries
	for i := 0; i < 100; i++ {
		key := []byte{byte(i / 256), byte(i % 256)}
		value := make([]byte, 50)
		if err := mt.Put(key, value); err != nil {
			t.Fatalf("Failed to put: %v", err)
		}
	}

	mem := mt.ApproximateMemoryUsage()
	if mem < 1000 {
		t.Errorf("Memory usage seems too low: %d", mem)
	}
}

func TestMemTableForEach(t *testing.T) {
	tmpfile, err := os.CreateTemp("", "memtable_foreach_")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	defer os.Remove(tmpfile.Name())
	tmpfile.Close()

	mt, err := NewMemTable(tmpfile.Name(), 1024*1024)
	if err != nil {
		t.Fatalf("Failed to create MemTable: %v", err)
	}
	defer mt.Close()

	// Put entries
	for i := 0; i < 5; i++ {
		key := []byte{byte(i)}
		if err := mt.Put(key, []byte("value")); err != nil {
			t.Fatalf("Failed to put: %v", err)
		}
	}

	// ForEach
	count := 0
	mt.ForEach(func(entry *Entry) bool {
		count++
		return true
	})

	if count != 5 {
		t.Errorf("Expected 5 entries, got %d", count)
	}
}

func TestMemTableClear(t *testing.T) {
	tmpfile, err := os.CreateTemp("", "memtable_clear_")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	defer os.Remove(tmpfile.Name())
	tmpfile.Close()

	mt, err := NewMemTable(tmpfile.Name(), 1024*1024)
	if err != nil {
		t.Fatalf("Failed to create MemTable: %v", err)
	}
	defer mt.Close()

	// Put entries
	if err := mt.Put([]byte("key"), []byte("value")); err != nil {
		t.Fatalf("Failed to put: %v", err)
	}

	// Clear
	mt.Clear()

	if mt.EntryCount() != 0 {
		t.Errorf("Expected 0 entries, got %d", mt.EntryCount())
	}

	if mt.IsFrozen() {
		t.Error("Expected unfrozen MemTable after clear")
	}
}

