package lsm

import (
	"encoding/binary"
	"fmt"
	"os"
	"sort"
	"sync"
)

// SSTable (Sorted String Table) stores sorted key-value pairs on disk
type SSTable struct {
	path        string
	file        *os.File
	indexOffset int64        // Offset to index block
	entries     []*IndexEntry // In-memory index
	mu          sync.RWMutex
	size        int64
}

// IndexEntry represents an entry in the index block
type IndexEntry struct {
	Key    []byte
	Offset int64
}

// DataBlock represents a block of key-value pairs
type DataBlock struct {
	Entries []*Entry
}

// SSTableConfig contains configuration for SSTable creation
type SSTableConfig struct {
	BlockSize int64 // Size of each data block
	Filename  string
}

// NewSSTable creates a new SSTable from a list of entries
func NewSSTable(config *SSTableConfig, entries []*Entry) (*SSTable, error) {
	// Ensure entries are sorted by key
	sort.Slice(entries, func(i, j int) bool {
		return bytesCompare(entries[i].Key, entries[j].Key) < 0
	})

	// Create file
	file, err := os.Create(config.Filename)
	if err != nil {
		return nil, fmt.Errorf("failed to create SSTable file: %w", err)
	}

	st := &SSTable{
		path:    config.Filename,
		file:    file,
		entries: []*IndexEntry{},
		size:    0,
	}

	// Write data blocks
	if err := st.writeDataBlocks(entries, config.BlockSize); err != nil {
		st.file.Close()
		return nil, err
	}

	// Write index block
	indexOffset := st.size
	if err := st.writeIndexBlock(); err != nil {
		st.file.Close()
		return nil, err
	}

	// Write footer
	if err := st.writeFooter(indexOffset); err != nil {
		st.file.Close()
		return nil, err
	}

	return st, nil
}

// writeDataBlocks writes key-value pairs as data blocks
func (st *SSTable) writeDataBlocks(entries []*Entry, blockSize int64) error {
	if len(entries) == 0 {
		return nil
	}

	var block []*Entry
	var blockByteSize int64

	for _, entry := range entries {
		entrySize := int64(len(entry.Key) + len(entry.Value) + 8) // key + value + lengths

		// Start new block if current block exceeds blockSize
		if blockByteSize > 0 && blockByteSize+entrySize > blockSize {
			if err := st.writeDataBlock(block); err != nil {
				return err
			}
			block = []*Entry{}
			blockByteSize = 0
		}

		block = append(block, entry)
		blockByteSize += entrySize
	}

	// Write remaining block
	if len(block) > 0 {
		if err := st.writeDataBlock(block); err != nil {
			return err
		}
	}

	return nil
}

// writeDataBlock writes a single data block
func (st *SSTable) writeDataBlock(entries []*Entry) error {
	if len(entries) == 0 {
		return nil
	}

	// Add index entry for first key in block
	st.entries = append(st.entries, &IndexEntry{
		Key:    append([]byte{}, entries[0].Key...),
		Offset: st.size,
	})

	// Encode block entries
	for _, entry := range entries {
		// Format: [4B: key len][4B: value len][key][value]
		keyLen := uint32(len(entry.Key))
		valueLen := uint32(len(entry.Value))

		// Write key length
		keyLenBuf := make([]byte, 4)
		binary.BigEndian.PutUint32(keyLenBuf, keyLen)
		if _, err := st.file.Write(keyLenBuf); err != nil {
			return fmt.Errorf("failed to write key length: %w", err)
		}
		st.size += 4

		// Write value length
		valueLenBuf := make([]byte, 4)
		binary.BigEndian.PutUint32(valueLenBuf, valueLen)
		if _, err := st.file.Write(valueLenBuf); err != nil {
			return fmt.Errorf("failed to write value length: %w", err)
		}
		st.size += 4

		// Write key
		if _, err := st.file.Write(entry.Key); err != nil {
			return fmt.Errorf("failed to write key: %w", err)
		}
		st.size += int64(len(entry.Key))

		// Write value
		if _, err := st.file.Write(entry.Value); err != nil {
			return fmt.Errorf("failed to write value: %w", err)
		}
		st.size += int64(len(entry.Value))
	}

	return nil
}

// writeIndexBlock writes the index block
func (st *SSTable) writeIndexBlock() error {
	// Format:
	// [4B: num entries]
	// [IndexEntry 0]: [4B: key len][key][8B: offset]
	// [IndexEntry 1]: [4B: key len][key][8B: offset]
	// ...

	// Write number of entries
	numEntriesBuf := make([]byte, 4)
	binary.BigEndian.PutUint32(numEntriesBuf, uint32(len(st.entries)))
	if _, err := st.file.Write(numEntriesBuf); err != nil {
		return fmt.Errorf("failed to write index entry count: %w", err)
	}
	st.size += 4

	// Write index entries
	for _, indexEntry := range st.entries {
		// Write key length
		keyLenBuf := make([]byte, 4)
		binary.BigEndian.PutUint32(keyLenBuf, uint32(len(indexEntry.Key)))
		if _, err := st.file.Write(keyLenBuf); err != nil {
			return fmt.Errorf("failed to write index key length: %w", err)
		}
		st.size += 4

		// Write key
		if _, err := st.file.Write(indexEntry.Key); err != nil {
			return fmt.Errorf("failed to write index key: %w", err)
		}
		st.size += int64(len(indexEntry.Key))

		// Write offset
		offsetBuf := make([]byte, 8)
		binary.BigEndian.PutUint64(offsetBuf, uint64(indexEntry.Offset))
		if _, err := st.file.Write(offsetBuf); err != nil {
			return fmt.Errorf("failed to write index offset: %w", err)
		}
		st.size += 8
	}

	return nil
}

// writeFooter writes the footer with index offset
func (st *SSTable) writeFooter(indexOffset int64) error {
	// Format: [8B: index offset]
	footerBuf := make([]byte, 8)
	binary.BigEndian.PutUint64(footerBuf, uint64(indexOffset))
	if _, err := st.file.Write(footerBuf); err != nil {
		return fmt.Errorf("failed to write footer: %w", err)
	}
	st.size += 8

	return st.file.Sync()
}

// OpenSSTable opens an existing SSTable file
func OpenSSTable(path string) (*SSTable, error) {
	file, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("failed to open SSTable file: %w", err)
	}

	st := &SSTable{
		path:    path,
		file:    file,
		entries: []*IndexEntry{},
	}

	// Read file size
	stat, err := file.Stat()
	if err != nil {
		file.Close()
		return nil, fmt.Errorf("failed to stat SSTable file: %w", err)
	}
	st.size = stat.Size()

	// Read footer (last 8 bytes)
	footerBuf := make([]byte, 8)
	if _, err := file.ReadAt(footerBuf, st.size-8); err != nil {
		file.Close()
		return nil, fmt.Errorf("failed to read footer: %w", err)
	}

	indexOffset := int64(binary.BigEndian.Uint64(footerBuf))

	// Read index block
	if err := st.readIndexBlock(indexOffset); err != nil {
		file.Close()
		return nil, err
	}

	return st, nil
}

// readIndexBlock reads the index block from disk
func (st *SSTable) readIndexBlock(offset int64) error {
	// Read number of entries
	numEntriesBuf := make([]byte, 4)
	if _, err := st.file.ReadAt(numEntriesBuf, offset); err != nil {
		return fmt.Errorf("failed to read index entry count: %w", err)
	}

	numEntries := binary.BigEndian.Uint32(numEntriesBuf)
	pos := offset + 4

	// Read index entries
	for i := uint32(0); i < numEntries; i++ {
		// Read key length
		keyLenBuf := make([]byte, 4)
		if _, err := st.file.ReadAt(keyLenBuf, pos); err != nil {
			return fmt.Errorf("failed to read index key length: %w", err)
		}
		keyLen := binary.BigEndian.Uint32(keyLenBuf)
		pos += 4

		// Read key
		keyBuf := make([]byte, keyLen)
		if _, err := st.file.ReadAt(keyBuf, pos); err != nil {
			return fmt.Errorf("failed to read index key: %w", err)
		}
		pos += int64(keyLen)

		// Read offset
		offsetBuf := make([]byte, 8)
		if _, err := st.file.ReadAt(offsetBuf, pos); err != nil {
			return fmt.Errorf("failed to read index offset: %w", err)
		}
		blockOffset := int64(binary.BigEndian.Uint64(offsetBuf))
		pos += 8

		st.entries = append(st.entries, &IndexEntry{
			Key:    keyBuf,
			Offset: blockOffset,
		})
	}

	return nil
}

// Get retrieves a value by key
func (st *SSTable) Get(key []byte) ([]byte, bool) {
	st.mu.RLock()
	defer st.mu.RUnlock()

	if len(st.entries) == 0 {
		return nil, false
	}

	// Binary search to find the right block
	blockIdx := sort.Search(len(st.entries), func(i int) bool {
		return bytesCompare(st.entries[i].Key, key) >= 0
	})

	if blockIdx > 0 {
		blockIdx--
	}

	// Read from the block
	return st.getFromBlock(blockIdx, key)
}

// getFromBlock reads a value from a specific block
func (st *SSTable) getFromBlock(blockIdx int, key []byte) ([]byte, bool) {
	if blockIdx >= len(st.entries) {
		return nil, false
	}

	// Determine block range
	startOffset := st.entries[blockIdx].Offset
	var endOffset int64
	if blockIdx+1 < len(st.entries) {
		endOffset = st.entries[blockIdx+1].Offset
	} else {
		// Last block: read until index starts
		for i := range st.entries {
			st.indexOffset = st.entries[i].Offset
		}
		endOffset = st.indexOffset
	}

	// Read block data
	blockData := make([]byte, endOffset-startOffset)
	if _, err := st.file.ReadAt(blockData, startOffset); err != nil {
		return nil, false
	}

	// Search for key in block
	pos := 0
	for pos < len(blockData) {
		if pos+8 > len(blockData) {
			break
		}

		// Read key length
		keyLen := binary.BigEndian.Uint32(blockData[pos : pos+4])
		pos += 4

		// Read value length
		valueLen := binary.BigEndian.Uint32(blockData[pos : pos+4])
		pos += 4

		if pos+int(keyLen)+int(valueLen) > len(blockData) {
			break
		}

		// Read key
		entryKey := blockData[pos : pos+int(keyLen)]
		pos += int(keyLen)

		// Read value
		entryValue := blockData[pos : pos+int(valueLen)]
		pos += int(valueLen)

		// Check if this is our key
		if bytesCompare(entryKey, key) == 0 {
			return append([]byte{}, entryValue...), true
		}

		if bytesCompare(entryKey, key) > 0 {
			// Key not found (entries are sorted)
			return nil, false
		}
	}

	return nil, false
}

// Range returns all entries in the specified range
func (st *SSTable) Range(startKey, endKey []byte) []*Entry {
	st.mu.RLock()
	defer st.mu.RUnlock()

	var result []*Entry

	if len(st.entries) == 0 {
		return result
	}

	// Find starting block
	blockIdx := 0
	if len(startKey) > 0 {
		blockIdx = sort.Search(len(st.entries), func(i int) bool {
			return bytesCompare(st.entries[i].Key, startKey) >= 0
		})
		if blockIdx > 0 {
			blockIdx--
		}
	}

	// Read from blocks until endKey
	for i := blockIdx; i < len(st.entries); i++ {
		entries := st.readBlock(i)
		for _, entry := range entries {
			// Check start key
			if len(startKey) > 0 && bytesCompare(entry.Key, startKey) < 0 {
				continue
			}

			// Check end key
			if len(endKey) > 0 && bytesCompare(entry.Key, endKey) >= 0 {
				return result
			}

			result = append(result, entry)
		}
	}

	return result
}

// readBlock reads all entries from a specific block
func (st *SSTable) readBlock(blockIdx int) []*Entry {
	var entries []*Entry

	if blockIdx >= len(st.entries) {
		return entries
	}

	startOffset := st.entries[blockIdx].Offset
	var endOffset int64
	if blockIdx+1 < len(st.entries) {
		endOffset = st.entries[blockIdx+1].Offset
	} else {
		endOffset = st.indexOffset
	}

	blockData := make([]byte, endOffset-startOffset)
	if _, err := st.file.ReadAt(blockData, startOffset); err != nil {
		return entries
	}

	// Parse block data
	pos := 0
	for pos < len(blockData) {
		if pos+8 > len(blockData) {
			break
		}

		keyLen := binary.BigEndian.Uint32(blockData[pos : pos+4])
		pos += 4
		valueLen := binary.BigEndian.Uint32(blockData[pos : pos+4])
		pos += 4

		if pos+int(keyLen)+int(valueLen) > len(blockData) {
			break
		}

		key := append([]byte{}, blockData[pos:pos+int(keyLen)]...)
		pos += int(keyLen)

		value := append([]byte{}, blockData[pos:pos+int(valueLen)]...)
		pos += int(valueLen)

		entries = append(entries, &Entry{Key: key, Value: value})
	}

	return entries
}

// Close closes the SSTable file
func (st *SSTable) Close() error {
	st.mu.Lock()
	defer st.mu.Unlock()

	return st.file.Close()
}

// Size returns the file size
func (st *SSTable) Size() int64 {
	st.mu.RLock()
	defer st.mu.RUnlock()

	return st.size
}

// EntryCount returns the number of index entries (blocks)
func (st *SSTable) EntryCount() int {
	st.mu.RLock()
	defer st.mu.RUnlock()

	return len(st.entries)
}

