package lsm

import (
	"bytes"
	"fmt"
	"os"
	"testing"
)

func TestSSTableCreation(t *testing.T) {
	tmpfile, err := os.CreateTemp("", "sstable_test_")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	defer os.Remove(tmpfile.Name())
	tmpfile.Close()

	// Create entries
	entries := []*Entry{
		{Key: []byte("key1"), Value: []byte("value1")},
		{Key: []byte("key2"), Value: []byte("value2")},
		{Key: []byte("key3"), Value: []byte("value3")},
	}

	config := &SSTableConfig{
		BlockSize: 1024,
		Filename:  tmpfile.Name(),
	}

	st, err := NewSSTable(config, entries)
	if err != nil {
		t.Fatalf("Failed to create SSTable: %v", err)
	}
	defer st.Close()

	if st.EntryCount() == 0 {
		t.Error("Expected non-zero entry count")
	}

	if st.Size() == 0 {
		t.Error("Expected non-zero SSTable size")
	}
}

func TestSSTableGet(t *testing.T) {
	tmpfile, err := os.CreateTemp("", "sstable_get_")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	defer os.Remove(tmpfile.Name())
	tmpfile.Close()

	// Create entries
	entries := []*Entry{
		{Key: []byte("apple"), Value: []byte("fruit")},
		{Key: []byte("banana"), Value: []byte("fruit")},
		{Key: []byte("carrot"), Value: []byte("vegetable")},
	}

	config := &SSTableConfig{
		BlockSize: 1024,
		Filename:  tmpfile.Name(),
	}

	st, err := NewSSTable(config, entries)
	if err != nil {
		t.Fatalf("Failed to create SSTable: %v", err)
	}
	defer st.Close()

	// Test Get
	val, ok := st.Get([]byte("banana"))
	if !ok || !bytes.Equal(val, []byte("fruit")) {
		t.Errorf("Expected 'fruit', got %v", val)
	}

	// Test non-existent key
	_, ok = st.Get([]byte("date"))
	if ok {
		t.Error("Expected key not found")
	}
}

func TestSSTableRange(t *testing.T) {
	tmpfile, err := os.CreateTemp("", "sstable_range_")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	defer os.Remove(tmpfile.Name())
	tmpfile.Close()

	// Create entries
	entries := make([]*Entry, 0)
	for i := 0; i < 10; i++ {
		key := []byte(fmt.Sprintf("key_%02d", i))
		value := []byte(fmt.Sprintf("value_%d", i))
		entries = append(entries, &Entry{Key: key, Value: value})
	}

	config := &SSTableConfig{
		BlockSize: 256, // Smaller blocks to test multi-block range
		Filename:  tmpfile.Name(),
	}

	st, err := NewSSTable(config, entries)
	if err != nil {
		t.Fatalf("Failed to create SSTable: %v", err)
	}
	defer st.Close()

	// Test range query
	result := st.Range([]byte("key_03"), []byte("key_07"))
	if len(result) == 0 {
		t.Error("Expected range results")
	}

	// Verify results are sorted
	for i := 1; i < len(result); i++ {
		if bytesCompare(result[i-1].Key, result[i].Key) > 0 {
			t.Error("Range results not sorted")
		}
	}
}

func TestSSTableOpen(t *testing.T) {
	tmpfile, err := os.CreateTemp("", "sstable_open_")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	defer os.Remove(tmpfile.Name())
	tmpfile.Close()

	// Create and write SSTable
	entries := []*Entry{
		{Key: []byte("a"), Value: []byte("1")},
		{Key: []byte("b"), Value: []byte("2")},
		{Key: []byte("c"), Value: []byte("3")},
	}

	config := &SSTableConfig{
		BlockSize: 1024,
		Filename:  tmpfile.Name(),
	}

	st, err := NewSSTable(config, entries)
	if err != nil {
		t.Fatalf("Failed to create SSTable: %v", err)
	}
	st.Close()

	// Open existing SSTable
	st2, err := OpenSSTable(tmpfile.Name())
	if err != nil {
		t.Fatalf("Failed to open SSTable: %v", err)
	}
	defer st2.Close()

	// Test Get on opened SSTable
	val, ok := st2.Get([]byte("b"))
	if !ok || !bytes.Equal(val, []byte("2")) {
		t.Errorf("Expected '2', got %v", val)
	}
}

func TestSSTableLargeFile(t *testing.T) {
	tmpfile, err := os.CreateTemp("", "sstable_large_")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	defer os.Remove(tmpfile.Name())
	tmpfile.Close()

	// Create 1000 entries
	entries := make([]*Entry, 0)
	for i := 0; i < 1000; i++ {
		key := []byte(fmt.Sprintf("key_%06d", i))
		value := make([]byte, 100)
		entries = append(entries, &Entry{Key: key, Value: value})
	}

	config := &SSTableConfig{
		BlockSize: 4096, // 4KB blocks
		Filename:  tmpfile.Name(),
	}

	st, err := NewSSTable(config, entries)
	if err != nil {
		t.Fatalf("Failed to create SSTable: %v", err)
	}
	defer st.Close()

	// Test Get on random entry
	val, ok := st.Get([]byte("key_000500"))
	if !ok || len(val) != 100 {
		t.Error("Failed to get entry from large SSTable")
	}
}

func TestSSTableMultipleBlocks(t *testing.T) {
	tmpfile, err := os.CreateTemp("", "sstable_multi_")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	defer os.Remove(tmpfile.Name())
	tmpfile.Close()

	// Create entries that will span multiple blocks
	entries := make([]*Entry, 0)
	for i := 0; i < 50; i++ {
		key := []byte(fmt.Sprintf("key_%03d", i))
		value := make([]byte, 100)
		entries = append(entries, &Entry{Key: key, Value: value})
	}

	config := &SSTableConfig{
		BlockSize: 256, // Small blocks to force multiple blocks
		Filename:  tmpfile.Name(),
	}

	st, err := NewSSTable(config, entries)
	if err != nil {
		t.Fatalf("Failed to create SSTable: %v", err)
	}
	defer st.Close()

	if st.EntryCount() < 2 {
		t.Errorf("Expected multiple blocks, got %d", st.EntryCount())
	}

	// Test Get across blocks
	val, ok := st.Get([]byte("key_025"))
	if !ok || len(val) != 100 {
		t.Error("Failed to get entry across blocks")
	}
}

func TestSSTableEmptyEntries(t *testing.T) {
	tmpfile, err := os.CreateTemp("", "sstable_empty_")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	defer os.Remove(tmpfile.Name())
	tmpfile.Close()

	config := &SSTableConfig{
		BlockSize: 1024,
		Filename:  tmpfile.Name(),
	}

	// Create SSTable with empty entries
	st, err := NewSSTable(config, []*Entry{})
	if err != nil {
		t.Fatalf("Failed to create empty SSTable: %v", err)
	}
	defer st.Close()

	if st.EntryCount() != 0 {
		t.Errorf("Expected 0 blocks, got %d", st.EntryCount())
	}
}

func TestSSTableRangeFullSpan(t *testing.T) {
	tmpfile, err := os.CreateTemp("", "sstable_range_full_")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	defer os.Remove(tmpfile.Name())
	tmpfile.Close()

	entries := []*Entry{
		{Key: []byte("a"), Value: []byte("1")},
		{Key: []byte("b"), Value: []byte("2")},
		{Key: []byte("c"), Value: []byte("3")},
		{Key: []byte("d"), Value: []byte("4")},
	}

	config := &SSTableConfig{
		BlockSize: 1024,
		Filename:  tmpfile.Name(),
	}

	st, err := NewSSTable(config, entries)
	if err != nil {
		t.Fatalf("Failed to create SSTable: %v", err)
	}
	defer st.Close()

	// Full range (no limits)
	result := st.Range(nil, nil)
	if len(result) != 4 {
		t.Errorf("Expected 4 entries, got %d", len(result))
	}
}

func TestSSTableGetNonExistent(t *testing.T) {
	tmpfile, err := os.CreateTemp("", "sstable_nonexist_")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	defer os.Remove(tmpfile.Name())
	tmpfile.Close()

	entries := []*Entry{
		{Key: []byte("apple"), Value: []byte("1")},
		{Key: []byte("cherry"), Value: []byte("3")},
	}

	config := &SSTableConfig{
		BlockSize: 1024,
		Filename:  tmpfile.Name(),
	}

	st, err := NewSSTable(config, entries)
	if err != nil {
		t.Fatalf("Failed to create SSTable: %v", err)
	}
	defer st.Close()

	// Try to get non-existent key between two existing keys
	_, ok := st.Get([]byte("banana"))
	if ok {
		t.Error("Expected key not found")
	}
}

