package lsm

import (
	"encoding/binary"
	"fmt"
	"os"
	"sort"
	"sync"
)

// SSTable (Sorted String Table) stores sorted key-value pairs on disk
type SSTable struct {
	path        string
	file        *os.File
	indexOffset int64        // Offset to index block
	entries     []*IndexEntry // In-memory index
	mu          sync.RWMutex
	size        int64
}

// IndexEntry represents an entry in the index block
type IndexEntry struct {
	Key    []byte
	Offset int64
}

// DataBlock represents a block of key-value pairs
type DataBlock struct {
	Entries []*Entry
}

// SSTableConfig contains configuration for SSTable creation
type SSTableConfig struct {
	BlockSize int64 // Size of each data block
	Filename  string
}

// NewSSTable creates a new SSTable from a list of entries
func NewSSTable(config *SSTableConfig, entries []*Entry) (*SSTable, error) {
	// Ensure entries are sorted by key
	sort.Slice(entries, func(i, j int) bool {
		return bytesCompare(entries[i].Key, entries[j].Key) < 0
	})

	// Create file
	file, err := os.Create(config.Filename)
	if err != nil {
		return nil, fmt.Errorf("failed to create SSTable file: %w", err)
	}

	st := &SSTable{
		path:    config.Filename,
		file:    file,
		entries: []*IndexEntry{},
		size:    0,
	}

	// Write data blocks
	if err := st.writeDataBlocks(entries, config.BlockSize); err != nil {
		st.file.Close()
		return nil, err
	}

	// Store index offset (start of index block)
	st.indexOffset = st.size

	// Write index block
	if err := st.writeIndexBlock(); err != nil {
		st.file.Close()
		return nil, err
	}

	// Write footer
	if err := st.writeFooter(indexOffset); err != nil {
		st.file.Close()
		return nil, err
	}

	return st, nil
}

// writeDataBlocks writes key-value pairs as data blocks
func (st *SSTable) writeDataBlocks(entries []*Entry, blockSize int64) error {
	if len(entries) == 0 {
		return nil
	}

	var block []*Entry
	var blockByteSize int64

	for _, entry := range entries {
		entrySize := int64(len(entry.Key) + len(entry.Value) + 8) // key + value + lengths

		// Start new block if current block exceeds blockSize
		if blockByteSize > 0 && blockByteSize+entrySize > blockSize {
			if err := st.writeDataBlock(block); err != nil {
				return err
			}
			block = []*Entry{}
			blockByteSize = 0
		}

		block = append(block, entry)
		blockByteSize += entrySize
	}

	// Write remaining block
	if len(block) > 0 {
		if err := st.writeDataBlock(block); err != nil {
			return err
		}
	}

	return nil
}

// writeDataBlock writes a single data block
func (st *SSTable) writeDataBlock(entries []*Entry) error {
	if len(entries) == 0 {
		return nil
	}

	// Add index entry for first key in block
	st.entries = append(st.entries, &IndexEntry{
		Key:    append([]byte{}, entries[0].Key...),
		Offset: st.size,
	})

	// Encode block entries
	for _, entry := range entries {
		// Format: [4B: key len][4B: value len][key][value]
		keyLen := uint32(len(entry.Key))
		valueLen := uint32(len(entry.Value))

		// Write key length
		keyLenBuf := make([]byte, 4)
		binary.BigEndian.PutUint32(keyLenBuf, keyLen)
		if _, err := st.file.Write(keyLenBuf); err != nil {
			return fmt.Errorf("failed to write key length: %w", err)
		}
		st.size += 4

		// Write value length
		valueLenBuf := make([]byte, 4)
		binary.BigEndian.PutUint32(valueLenBuf, valueLen)
		if _, err := st.file.Write(valueLenBuf); err != nil {
			return fmt.Errorf("failed to write value length: %w", err)
		}
		st.size += 4

		// Write key
		if _, err := st.file.Write(entry.Key); err != nil {
			return fmt.Errorf("failed to write key: %w", err)
		}
		st.size += int64(len(entry.Key))

		// Write value
		if _, err := st.file.Write(entry.Value); err != nil {
			return fmt.Errorf("failed to write value: %w", err)
		}
		st.size += int64(len(entry.Value))
	}

	return nil
}

// writeIndexBlock writes the index block
func (st *SSTable) writeIndexBlock() error {
	// Format:
	// [4B: num entries]
	// [IndexEntry 0]: [4B: key len][key][8B: offset]
	// [IndexEntry 1]: [4B: key len][key][8B: offset]
	// ...

