package lsm

import (
	"fmt"
	"sort"
	"sync"
	"time"
)

// Compactor manages background compaction of SSTables
type Compactor struct {
	ssTables    []*SSTable
	memTable    *MemTable
	config      *CompactorConfig
	stopCh      chan struct{}
	mu          sync.RWMutex
	isRunning   bool
	lastCompact time.Time
}

// CompactorConfig contains configuration for the compactor
type CompactorConfig struct {
	CompactInterval   time.Duration // Interval between compactions
	MaxLevelSize      int64         // Max size before promoting to next level
	MaxSSTables       int           // Max SSTables before compacting
	BlockSize         int64         // Block size for new SSTables
	CompactionPath    string        // Directory for compacted SSTables
}

// DefaultCompactorConfig returns default compactor configuration
func DefaultCompactorConfig() *CompactorConfig {
	return &CompactorConfig{
		CompactInterval: 10 * time.Second,
		MaxLevelSize:    10 * 1024 * 1024, // 10MB
		MaxSSTables:     4,
		BlockSize:       4096,
		CompactionPath:  "./sstables",
	}
}

// NewCompactor creates a new compactor
func NewCompactor(config *CompactorConfig) *Compactor {
	return &Compactor{
		ssTables: []*SSTable{},
		config:   config,
		stopCh:   make(chan struct{}),
	}
}

// Start starts the background compaction process
func (c *Compactor) Start() {
	c.mu.Lock()
	defer c.mu.Unlock()

	if c.isRunning {
		return
	}

	c.isRunning = true
	go c.run()
}

// Stop stops the background compaction process
func (c *Compactor) Stop() {
	c.mu.Lock()
	defer c.mu.Unlock()

	if !c.isRunning {
		return
	}

	c.isRunning = false
	close(c.stopCh)
}

// run is the main compaction loop
func (c *Compactor) run() {
	ticker := time.NewTicker(c.config.CompactInterval)
	defer ticker.Stop()

	for {
		select {
		case <-c.stopCh:
			return
		case <-ticker.C:
			c.tryCompact()
		}
	}
}

// tryCompact attempts to compact if necessary
func (c *Compactor) tryCompact() {
	c.mu.Lock()
	defer c.mu.Unlock()

	// Check if compaction is needed
	if !c.shouldCompact() {
		return
	}

	// Perform compaction
	if err := c.compact(); err != nil {
		fmt.Printf("[Compactor] Compaction failed: %v\n", err)
		return
	}

	c.lastCompact = time.Now()
	fmt.Printf("[Compactor] Compaction completed, %d SSTables\n", len(c.ssTables))
}

// shouldCompact checks if compaction is needed
func (c *Compactor) shouldCompact() bool {
	// Too many SSTables
	if len(c.ssTables) >= c.config.MaxSSTables {
		return true
	}

	// Calculate total size
	var totalSize int64
	for _, st := range c.ssTables {
		totalSize += st.Size()
	}

	// Size exceeds threshold
	if totalSize > c.config.MaxLevelSize {
		return true
	}

	// Regular compaction interval
	if time.Since(c.lastCompact) > c.config.CompactInterval*2 && len(c.ssTables) > 1 {
		return true
	}

	return false
}

// compact merges multiple SSTables into one
func (c *Compactor) compact() error {
	if len(c.ssTables) < 2 {
		return nil
	}

	// Collect all entries from all SSTables
	var allEntries []*Entry

	for _, st := range c.ssTables {
		entries := st.Range(nil, nil)
		allEntries = append(allEntries, entries...)
	}

	// Sort by key
	sort.Slice(allEntries, func(i, j int) bool {
		return bytesCompare(allEntries[i].Key, allEntries[j].Key) < 0
	})

	// Remove duplicates (keep last value)
	deduped := deduplicateEntries(allEntries)

	// Create new SSTable from merged entries
	filename := fmt.Sprintf("%s/sstable_%d.sst", c.config.CompactionPath, time.Now().UnixNano())
	config := &SSTableConfig{
		BlockSize: c.config.BlockSize,
		Filename:  filename,
	}

	newST, err := NewSSTable(config, deduped)
	if err != nil {
		return fmt.Errorf("failed to create compacted SSTable: %w", err)
	}

	// Close old SSTables
	for _, st := range c.ssTables {
		st.Close()
	}

	// Replace with new SSTable
	c.ssTables = []*SSTable{newST}

	return nil
}

// deduplicateEntries removes duplicate keys, keeping the last value
func deduplicateEntries(entries []*Entry) []*Entry {
	if len(entries) == 0 {
		return entries
	}

	// Map to track last value for each key
	seen := make(map[string]*Entry)
	for _, entry := range entries {
		key := string(entry.Key)
		seen[key] = entry
	}

	// Reconstruct deduplicated list in sorted order
	var keys []string
	for key := range seen {
		keys = append(keys, key)
	}
	sort.Strings(keys)

	var result []*Entry
	for _, key := range keys {
		result = append(result, seen[key])
	}

	return result
}

// AddSSTable adds an SSTable to be compacted
func (c *Compactor) AddSSTable(st *SSTable) {
	c.mu.Lock()
	defer c.mu.Unlock()

	c.ssTables = append(c.ssTables, st)
}

// GetSSTables returns current SSTables
func (c *Compactor) GetSSTables() []*SSTable {
	c.mu.RLock()
	defer c.mu.RUnlock()

	result := make([]*SSTable, len(c.ssTables))
	copy(result, c.ssTables)
	return result
}

// SSTableCount returns the number of SSTables
func (c *Compactor) SSTableCount() int {
	c.mu.RLock()
	defer c.mu.RUnlock()

	return len(c.ssTables)
}

// TotalSize returns total size of all SSTables
func (c *Compactor) TotalSize() int64 {
	c.mu.RLock()
	defer c.mu.RUnlock()

	var total int64
	for _, st := range c.ssTables {
		total += st.Size()
	}

	return total
}

// IsRunning returns whether compactor is running
func (c *Compactor) IsRunning() bool {
	c.mu.RLock()
	defer c.mu.RUnlock()

	return c.isRunning
}

// LastCompactTime returns the last compaction time
func (c *Compactor) LastCompactTime() time.Time {
	c.mu.RLock()
	defer c.mu.RUnlock()

	return c.lastCompact
}

// CompactionStats returns statistics about compaction
type CompactionStats struct {
	SSTableCount  int
	TotalSize     int64
	IsRunning     bool
	LastCompact   time.Time
	ShouldCompact bool
}

// GetStats returns current compaction statistics
func (c *Compactor) GetStats() CompactionStats {
	c.mu.RLock()
	defer c.mu.RUnlock()

	return CompactionStats{
		SSTableCount:  len(c.ssTables),
		TotalSize:     c.getTotalSize(),
		IsRunning:     c.isRunning,
		LastCompact:   c.lastCompact,
		ShouldCompact: c.shouldCompact(),
	}
}

// getTotalSize helper (must be called with lock held)
func (c *Compactor) getTotalSize() int64 {
	var total int64
	for _, st := range c.ssTables {
		total += st.Size()
	}
	return total
}

